package com.codex.sessionchronicle;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexSessionChroniclePluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexSessionChroniclePlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.sessionchronicle;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CodexSessionChronicleConfig.GROUP)
public interface CodexSessionChronicleConfig extends Config
{
	String GROUP = "codexsessionchronicle";

	@ConfigSection(
		name = "Sessions",
		description = "When a session begins and ends, and what it remembers",
		position = 0
	)
	String sessions = "sessions";

	@ConfigSection(
		name = "Display",
		description = "What Session Chronicle shows in the game and on the card",
		position = 1
	)
	String display = "display";

	@Range(min = 1, max = 240)
	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "breakMinutes",
		name = "Break allowance",
		description = "Log back in within this long and the same session carries on; stay away longer and a new one begins",
		position = 0,
		section = sessions
	)
	default int breakMinutes()
	{
		return 15;
	}

	@Range(min = 5, max = 100)
	@ConfigItem(
		keyName = "journalSize",
		name = "Sessions kept",
		description = "How many finished sessions the journal keeps for each account",
		position = 1,
		section = sessions
	)
	default int journalSize()
	{
		return 40;
	}

	@ConfigItem(
		keyName = "valuableDrop",
		name = "Notable drop value",
		description = "A single drop worth at least this many coins becomes one of the session's moments",
		position = 2,
		section = sessions
	)
	default int valuableDrop()
	{
		return 500_000;
	}

	@ConfigItem(
		keyName = "showTicker",
		name = "Session ticker",
		description = "Show a small plaque in the game view with the session's time, experience and loot",
		position = 0,
		section = display
	)
	default boolean showTicker()
	{
		return false;
	}

	@ConfigItem(
		keyName = "chatRecap",
		name = "Recap last session",
		description = "When a new session begins, put a line in the chat box recapping the one before",
		position = 1,
		section = display
	)
	default boolean chatRecap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "nameOnCard",
		name = "Name on card",
		description = "Write your character's name on the session card",
		position = 2,
		section = display
	)
	default boolean nameOnCard()
	{
		return true;
	}
}

package com.codex.sessionchronicle;

import com.codex.sessionchronicle.core.ChatParser;
import com.codex.sessionchronicle.core.Chronicle;
import com.codex.sessionchronicle.core.Journal;
import com.codex.sessionchronicle.core.Moment;
import com.codex.sessionchronicle.core.Session;
import com.codex.sessionchronicle.core.Summary;
import com.codex.sessionchronicle.overlay.SessionTicker;
import com.codex.sessionchronicle.ui.CardActions;
import com.codex.sessionchronicle.ui.ChroniclePanel;
import com.codex.sessionchronicle.ui.Format;
import com.codex.sessionchronicle.ui.Icons;
import com.codex.sessionchronicle.ui.SessionActions;
import com.codex.sessionchronicle.ui.ItemIcons;
import com.codex.sessionchronicle.ui.Sigil;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Type;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.Text;
import net.runelite.http.api.loottracker.LootRecordType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Codex Session Chronicle",
	description = "An automatic recap of every play session: experience, loot, kills and moments, saved to a journal and shareable as a card",
	tags = {"session", "recap", "summary", "journal", "xp", "loot", "kills", "share", "card", "codex"}
)
public class CodexSessionChroniclePlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexSessionChroniclePlugin.class);
	private static final String CURRENT_KEY = "current";
	private static final String JOURNAL_KEY = "journal";
	private static final Type JOURNAL_TYPE = new TypeToken<List<Session>>()
	{
	}.getType();
	/** Ticks between panel refreshes when only the clock and the experience moved. */
	private static final int REFRESH_TICKS = 5;
	/** Ticks to wait after logging in, so the stats the game sends at login are all in. */
	private static final int LOGIN_TICKS = 2;
	/** Ticks to keep ignoring stats after a minigame hands the player's own stats back. */
	private static final int GUARD_TICKS = 3;
	/** Ticks between saves of the session being lived, about a minute. */
	private static final int SAVE_TICKS = 100;
	/** How long a kill count stays fresh enough to name the personal best that follows it. */
	private static final long RECENT_KC_MS = 10_000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private CodexSessionChronicleConfig config;

	private final Chronicle chronicle = new Chronicle();
	private final SessionTicker ticker = new SessionTicker();

	private ChroniclePanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> expiry;

	private String profile;
	private List<Session> journal = Collections.emptyList();
	private List<Summary> pastSummaries = Collections.emptyList();
	private boolean pendingBegin;
	private int loginTicks;
	private boolean quietBegin;
	private boolean dirty;
	private boolean saveSoon;
	private int guardTicks;
	private int ticks;
	/** The session being lived as last saved or shown, so it can be written as the client closes. */
	private volatile String snapshot;
	private volatile String snapshotProfile;
	private String recentKc;
	private long recentKcAt;

	@Provides
	CodexSessionChronicleConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexSessionChronicleConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons items = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		Icons icons = name ->
		{
			try
			{
				return skillIconManager.getSkillImage(Skill.valueOf(name.toUpperCase()), true);
			}
			catch (IllegalArgumentException e)
			{
				return null;
			}
		};
		panel = new ChroniclePanel(items, icons, new CardActions()
		{
			@Override
			public void save(BufferedImage card, Summary session)
			{
				saveCard(card, session);
			}

			@Override
			public void copy(BufferedImage card)
			{
				copyCard(card);
			}
		}, new SessionActions()
		{
			@Override
			public void endSession()
			{
				clientThread.invoke(CodexSessionChroniclePlugin.this::endNow);
			}

			@Override
			public void removeSession(long startedAt)
			{
				clientThread.invoke(() -> forget(startedAt));
			}
		});
		panel.setShowName(config.nameOnCard());
		navButton = NavigationButton.builder()
			.tooltip("Codex Session Chronicle")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		ticker.setEnabled(config.showTicker());
		overlayManager.add(ticker);
		expiry = executor.scheduleWithFixedDelay(() -> clientThread.invoke(this::checkExpiry), 30, 30, TimeUnit.SECONDS);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			pendingBegin = client.getGameState() == GameState.LOGGED_IN;
			loginTicks = LOGIN_TICKS;
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		if (expiry != null)
		{
			expiry.cancel(false);
			expiry = null;
		}
		overlayManager.remove(ticker);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			chronicle.pause(System.currentTimeMillis());
			saveCurrent();
			chronicle.restore(null);
			profile = null;
			journal = Collections.emptyList();
			pastSummaries = Collections.emptyList();
			pendingBegin = false;
			snapshot = null;
		});
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			if (!chronicle.isLive() && !pendingBegin)
			{
				pendingBegin = true;
				loginTicks = 0;
			}
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			pendingBegin = false;
			if (chronicle.isLive())
			{
				chronicle.pause(System.currentTimeMillis());
				saveCurrent();
				dirty = true;
				publish();
			}
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		chronicle.pause(System.currentTimeMillis());
		saveCurrent();
		loadProfile();
		pendingBegin = client.getGameState() == GameState.LOGGED_IN;
		publish();
	}

	/** The client is closing: write the session as it last stood, since game ticks have stopped. */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		String json = snapshot;
		String key = snapshotProfile;
		if (json != null && key != null)
		{
			configManager.setConfiguration(CodexSessionChronicleConfig.GROUP, key, CURRENT_KEY, json);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// The plugin's own saves of the session and journal land here too, about once a minute;
		// only the two settings that change what is drawn are worth acting on.
		if (!CodexSessionChronicleConfig.GROUP.equals(event.getGroup()) || event.getProfile() != null
			|| (!"showTicker".equals(event.getKey()) && !"nameOnCard".equals(event.getKey())))
		{
			return;
		}
		ticker.setEnabled(config.showTicker());
		ChroniclePanel target = panel;
		if (target != null)
		{
			boolean showName = config.nameOnCard();
			SwingUtilities.invokeLater(() -> target.setShowName(showName));
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		long now = System.currentTimeMillis();
		if (pendingBegin && ++loginTicks > LOGIN_TICKS)
		{
			tryBegin(now);
		}
		if (!chronicle.isLive())
		{
			return;
		}
		guard();
		chronicle.tick(now);
		ticks++;
		Session current = chronicle.current();
		ticker.show(new SessionTicker.View(current.getPlayedMs(), now, true, current.totalXp(), current.lootValue()));
		if (saveSoon || ticks % SAVE_TICKS == 0)
		{
			saveCurrent();
		}
		if (dirty || ticks % REFRESH_TICKS == 0)
		{
			publish();
		}
	}

	/**
	 * Last Man Standing and the PvP Arena swap the player's stats for fixed ones and give them
	 * back afterwards. A world flagged Last Man Standing is an ordinary world otherwise (RuneLite's
	 * world hopper treats it as one), so only the in-game varbit counts for LMS. Neither is progress, so stats are ignored while swapped, and once they are
	 * back the session picks up from whatever the game now says.
	 */
	private void guard()
	{
		if (statsSwapped())
		{
			guardTicks = GUARD_TICKS;
			return;
		}
		if (guardTicks > 0 && --guardTicks == 0)
		{
			for (Skill skill : Skill.values())
			{
				chronicle.resume(skill.getName(), client.getSkillExperience(skill), client.getRealSkillLevel(skill));
			}
			dirty = true;
		}
	}

	private boolean statsSwapped()
	{
		return client.getVarbitValue(VarbitID.BR_INGAME) != 0
			|| client.getWorldType().contains(WorldType.PVP_ARENA);
	}

	/** Starts or picks up the session once the account and its stats are readable. */
	private void tryBegin(long now)
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null || client.getOverallExperience() <= 0 || statsSwapped())
		{
			return;
		}
		if (profile == null || !profile.equals(configManager.getRSProfileKey()))
		{
			loadProfile();
			if (profile == null)
			{
				return;
			}
		}
		pendingBegin = false;
		Session closed = chronicle.begin(now, player.getName(), config.breakMinutes() * 60_000L);
		if (closed != null)
		{
			file(closed);
		}
		boolean fresh = chronicle.current().getStartedAt() == now;
		for (Skill skill : Skill.values())
		{
			if (fresh)
			{
				chronicle.xp(skill.getName(), client.getSkillExperience(skill), client.getRealSkillLevel(skill), now);
			}
			else
			{
				chronicle.resume(skill.getName(), client.getSkillExperience(skill), client.getRealSkillLevel(skill));
			}
		}
		if (fresh && !quietBegin && config.chatRecap() && !journal.isEmpty())
		{
			recap(journal.get(0));
		}
		quietBegin = false;
		saveCurrent();
		dirty = true;
		publish();
	}

	/** The player asked to close the session now; a new one begins at once if they are in the game. */
	private void endNow()
	{
		if (chronicle.current() == null)
		{
			return;
		}
		chronicle.pause(System.currentTimeMillis());
		Session closed = chronicle.close();
		if (closed != null)
		{
			file(closed);
		}
		saveCurrent();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			pendingBegin = true;
			loginTicks = LOGIN_TICKS;
			quietBegin = true;
		}
		publish();
	}

	/** Takes one session out of the journal. */
	private void forget(long startedAt)
	{
		journal = Journal.remove(journal, startedAt);
		summarisePast();
		storeJournal();
		publish();
	}

	private void checkExpiry()
	{
		Session closed = chronicle.expire(System.currentTimeMillis(), config.breakMinutes() * 60_000L);
		if (closed != null)
		{
			file(closed);
			saveCurrent();
			publish();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!chronicle.isLive() || guardTicks > 0 || statsSwapped())
		{
			return;
		}
		List<Moment> moments = chronicle.xp(event.getSkill().getName(), event.getXp(), event.getLevel(), System.currentTimeMillis());
		if (!moments.isEmpty())
		{
			// A level is worth showing and keeping straight away; plain experience waits for the next refresh.
			dirty = true;
			saveSoon = true;
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		loot(npc == null ? null : npc.getName(), event.getItems(), 1);
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		// Kills arrive through NpcLootReceived on their own, and player kills are left out.
		LootRecordType type = event.getType();
		if (type == LootRecordType.NPC || type == LootRecordType.PLAYER)
		{
			return;
		}
		loot(event.getName(), event.getItems(), type == LootRecordType.EVENT ? Math.max(1, event.getAmount()) : 0);
	}

	private void loot(String source, Collection<ItemStack> items, int kills)
	{
		if (!chronicle.isLive())
		{
			return;
		}
		List<Session.Drop> drops = new ArrayList<>();
		for (ItemStack stack : items)
		{
			int id = itemManager.canonicalize(stack.getId());
			ItemComposition item = itemManager.getItemComposition(id);
			drops.add(new Session.Drop(id, item.getName(), stack.getQuantity(), itemManager.getItemPrice(id)));
		}
		List<Moment> moments = chronicle.loot(source == null ? null : Text.removeTags(source), drops, kills, config.valuableDrop(),
			System.currentTimeMillis());
		dirty = true;
		saveSoon |= !moments.isEmpty();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!chronicle.isLive() || (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM))
		{
			return;
		}
		String message = Text.removeTags(event.getMessage()).replace(' ', ' ').trim();
		long now = System.currentTimeMillis();
		ChatParser.KillCount kc = ChatParser.killCount(message);
		if (kc != null)
		{
			chronicle.killCount(kc.getName(), kc.getCount());
			recentKc = kc.getName();
			recentKcAt = now;
			dirty = true;
			return;
		}
		Moment moment = ChatParser.moment(message, now, now - recentKcAt <= RECENT_KC_MS ? recentKc : null);
		if (moment != null)
		{
			chronicle.moment(moment);
			dirty = true;
			saveSoon = true;
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Player player = client.getLocalPlayer();
		if (chronicle.isLive() && player != null && event.getActor() == player && !statsSwapped())
		{
			Actor foe = player.getInteracting();
			String killer = foe instanceof NPC && foe.getName() != null ? Text.removeTags(foe.getName()) : null;
			chronicle.death(System.currentTimeMillis(), killer);
			dirty = true;
			saveSoon = true;
		}
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		journal = Collections.emptyList();
		pastSummaries = Collections.emptyList();
		chronicle.restore(null);
		if (profile == null)
		{
			return;
		}
		try
		{
			String saved = configManager.getRSProfileConfiguration(CodexSessionChronicleConfig.GROUP, JOURNAL_KEY);
			if (saved != null && !saved.isEmpty())
			{
				List<Session> list = gson.fromJson(saved, JOURNAL_TYPE);
				if (list != null)
				{
					list.removeIf(s -> s == null);
					journal = list;
				}
			}
			String current = configManager.getRSProfileConfiguration(CodexSessionChronicleConfig.GROUP, CURRENT_KEY);
			if (current != null && !current.isEmpty())
			{
				chronicle.restore(gson.fromJson(current, Session.class));
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Could not read the saved chronicle, starting it afresh", e);
		}
		summarisePast();
		// A session left open when the client closed may have ended long ago.
		Session closed = chronicle.expire(System.currentTimeMillis(), config.breakMinutes() * 60_000L);
		if (closed != null)
		{
			file(closed);
			saveCurrent();
		}
	}

	private void file(Session closed)
	{
		journal = Journal.file(journal, closed, config.journalSize());
		summarisePast();
		storeJournal();
	}

	private void storeJournal()
	{
		if (profile != null)
		{
			configManager.setConfiguration(CodexSessionChronicleConfig.GROUP, profile, JOURNAL_KEY, gson.toJson(journal, JOURNAL_TYPE));
		}
	}

	private void summarisePast()
	{
		List<Summary> list = new ArrayList<>();
		for (Session s : journal)
		{
			list.add(Summary.of(s, Summary.State.ENDED));
		}
		pastSummaries = Collections.unmodifiableList(list);
	}

	private void saveCurrent()
	{
		saveSoon = false;
		Session current = chronicle.current();
		snapshot = current == null ? null : gson.toJson(current);
		snapshotProfile = profile;
		if (profile == null)
		{
			return;
		}
		if (current == null)
		{
			configManager.unsetConfiguration(CodexSessionChronicleConfig.GROUP, profile, CURRENT_KEY);
		}
		else
		{
			configManager.setConfiguration(CodexSessionChronicleConfig.GROUP, profile, CURRENT_KEY, snapshot);
		}
	}

	private void recap(Session last)
	{
		String line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Session Chronicle: ")
			.append(ChatColorType.NORMAL).append("a new session begins. Last time, " + Format.duration(last.getPlayedMs()) + " played, ")
			.append(ChatColorType.HIGHLIGHT).append(Format.xp(last.totalXp()) + " xp")
			.append(ChatColorType.NORMAL).append(" and ")
			.append(ChatColorType.HIGHLIGHT).append(Format.coins(last.lootValue()) + " loot")
			.append(ChatColorType.NORMAL).append(".")
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(line)
			.build());
	}

	/** Sends the panel a copy of the chronicle, so Swing never reads what the client thread is writing. */
	private void publish()
	{
		dirty = false;
		Session current = chronicle.current();
		Summary live = null;
		Session copy = null;
		if (current != null)
		{
			String json = gson.toJson(current);
			snapshot = json;
			snapshotProfile = profile;
			copy = gson.fromJson(json, Session.class);
			live = Summary.of(copy, chronicle.isLive() ? Summary.State.LIVE : Summary.State.PAUSED);
			ticker.show(new SessionTicker.View(copy.getPlayedMs(), System.currentTimeMillis(), chronicle.isLive(), copy.totalXp(), copy.lootValue()));
		}
		else
		{
			ticker.show(null);
		}
		Journal.Records records = Journal.records(journal, copy, System.currentTimeMillis(), ZoneId.systemDefault());
		Player player = client.getLocalPlayer();
		String name = client.getGameState() == GameState.LOGGED_IN && player != null ? player.getName() : null;
		List<Summary> past = pastSummaries;
		ChroniclePanel target = panel;
		if (target != null)
		{
			Summary shown = live;
			SwingUtilities.invokeLater(() -> target.update(shown, past, records, name));
		}
	}

	/** Asks where to save the card with RuneLite's own file chooser, then writes it there; runs on the Swing thread. */
	private void saveCard(BufferedImage card, Summary session)
	{
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save session card")
			.addExtensionFilter("PNG image", "png")
			.setDefaultExtension("png")
			.setFileName("Session " + Format.file(session.getStartedAt()) + ".png")
			.showDialog(panel);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}
		Filepath target = chosen.get(0);
		executor.execute(() ->
		{
			String note;
			try (OutputStream out = target.openOutputStream())
			{
				ImageIO.write(card, "png", out);
				note = "Saved as " + target.getFileName() + ".";
			}
			catch (IOException e)
			{
				log.warn("Could not save the session card", e);
				note = "The card could not be saved: " + e.getMessage();
			}
			String shown = note;
			ChroniclePanel view = panel;
			if (view != null)
			{
				SwingUtilities.invokeLater(() -> view.cardNote(shown));
			}
		});
	}

	private void copyCard(BufferedImage card)
	{
		String note;
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageTransfer(ImageTransfer.opaque(card)), null);
			note = "Copied. Paste it anywhere you share pictures.";
		}
		catch (IllegalStateException e)
		{
			note = "The clipboard is busy, try again in a moment.";
		}
		ChroniclePanel target = panel;
		if (target != null)
		{
			target.cardNote(note);
		}
	}
}

package com.codex.sessionchronicle;

import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import com.codex.sessionchronicle.ui.Theme;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/** Hands the card to the system clipboard as a picture. */
final class ImageTransfer implements Transferable
{
	private final BufferedImage image;

	ImageTransfer(BufferedImage image)
	{
		this.image = image;
	}

	/**
	 * The card on a solid backing. Some clipboards (Windows among them) drop transparency and
	 * would paint the card's rounded corners black, so they are filled with the card's own ink.
	 */
	static BufferedImage opaque(BufferedImage card)
	{
		BufferedImage out = new BufferedImage(card.getWidth(), card.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.setColor(Theme.INK_DEEP);
		g.fillRect(0, 0, out.getWidth(), out.getHeight());
		g.drawImage(card, 0, 0, null);
		g.dispose();
		return out;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return new DataFlavor[]{DataFlavor.imageFlavor};
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return DataFlavor.imageFlavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!isDataFlavorSupported(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return image;
	}
}

package com.codex.sessionchronicle.core;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the game's own messages for the things a session should remember. It takes the message
 * with its colour tags already removed and answers with what it found, or null.
 */
public final class ChatParser
{
	private static final Pattern KILL_COUNT = Pattern.compile(
		"^Your (?:completed |subdued )?(.+?) (?:kill |success |completion )?count is: ?([\\d,]+)\\b");
	private static final Pattern COLLECTION = Pattern.compile("^New item added to your collection log: (.+?)\\.?$");
	private static final Pattern QUEST = Pattern.compile("^Congratulations,? you've completed a quest: (.+?)\\.?$");
	private static final Pattern DIARY = Pattern.compile(
		"^Congratulations! You have completed all of the (\\w+) tasks in the (.+?) area\\b");
	private static final Pattern TASK = Pattern.compile(
		"^Congratulations, you've completed an? (\\w+) combat task: (.+?)(?: \\(\\d+ points?\\))?\\.?$");
	private static final Pattern CLUE = Pattern.compile("^You have completed ([\\d,]+) (\\w+) Treasure Trails?\\.?$");
	private static final Pattern BEST = Pattern.compile("^(.*?)(?:duration|time)(?: was)?: ?([\\d:.]+) ?\\(new personal best\\)");
	private static final String[] PET_LINES = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};

	/** A kill count the game announced. */
	public static final class KillCount
	{
		private final String name;
		private final int count;

		KillCount(String name, int count)
		{
			this.name = name;
			this.count = count;
		}

		public String getName()
		{
			return name;
		}

		public int getCount()
		{
			return count;
		}
	}

	private ChatParser()
	{
	}

	public static KillCount killCount(String message)
	{
		Matcher m = KILL_COUNT.matcher(message);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return new KillCount(m.group(1), Integer.parseInt(m.group(2).replace(",", "")));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * A moment the message tells of, or null.
	 *
	 * @param recentBoss the boss whose kill count was just announced, to name a personal best
	 */
	public static Moment moment(String message, long now, String recentBoss)
	{
		for (String line : PET_LINES)
		{
			if (message.startsWith(line))
			{
				boolean duplicate = line.contains("would have been");
				return new Moment(Moment.Kind.PET, now, duplicate ? "A pet, again" : "A pet followed you home",
					duplicate ? "You already had this one" : "The rarest drop of all", 0, 0);
			}
		}
		Matcher m = COLLECTION.matcher(message);
		if (m.find())
		{
			return new Moment(Moment.Kind.COLLECTION, now, m.group(1), "New collection log slot", 0, 0);
		}
		m = QUEST.matcher(message);
		if (m.find())
		{
			return new Moment(Moment.Kind.QUEST, now, m.group(1), "Quest complete", 0, 0);
		}
		m = DIARY.matcher(message);
		if (m.find())
		{
			return new Moment(Moment.Kind.DIARY, now, m.group(2) + " " + m.group(1) + " diary", "Achievement diary complete", 0, 0);
		}
		m = TASK.matcher(message);
		if (m.find())
		{
			return new Moment(Moment.Kind.TASK, now, m.group(2), capital(m.group(1)) + " combat task", 0, 0);
		}
		m = CLUE.matcher(message);
		if (m.find())
		{
			return new Moment(Moment.Kind.CLUE, now, capital(m.group(2)) + " clue scroll", "Treasure Trail number " + m.group(1), 0, 0);
		}
		m = BEST.matcher(message);
		if (m.find())
		{
			String what = m.group(1).replaceAll("(?i)\\b(fight|challenge|total|completion|overall)\\b", "").trim();
			if (what.isEmpty())
			{
				what = recentBoss == null ? "Personal best" : recentBoss;
			}
			return new Moment(Moment.Kind.BEST, now, what + " in " + m.group(2), "New personal best", 0, 0);
		}
		return null;
	}

	private static String capital(String word)
	{
		return word.isEmpty() ? word : Character.toUpperCase(word.charAt(0)) + word.substring(1).toLowerCase();
	}
}

package com.codex.sessionchronicle.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

/**
 * Keeps the session that is being lived. It opens one when the player logs in, picks the same
 * one back up if they return within the break allowance, and closes it once they have been away
 * longer. Everything is fed in by the plugin with the time it happened, so it runs the same in
 * tests as in the game. Not thread safe: the plugin only touches it on the client thread.
 */
public class Chronicle
{
	/** The longest gap between two ticks that still counts as play, so a frozen client does not. */
	static final long MAX_TICK_GAP_MS = 5_000;
	static final int MAX_MOMENTS = 200;
	/** How far apart a big drop and its collection log message can be and still be one moment. */
	static final long MERGE_MS = 10 * 60_000L;

	private Session current;
	private boolean live;
	private long lastTick;

	public Session current()
	{
		return current;
	}

	public boolean isLive()
	{
		return live && current != null;
	}

	/** Puts back a session saved before the client closed; it waits paused until the player is seen. */
	public void restore(Session saved)
	{
		current = saved;
		live = false;
	}

	/**
	 * The player is in the game. Continues the open session when it is theirs and they were away
	 * for no longer than the gap, otherwise starts a new one.
	 *
	 * @return the session this closed, or null
	 */
	public Session begin(long now, String player, long gapMs)
	{
		Session closed = null;
		if (current != null && (now - current.lastSeenAt > gapMs || !Objects.equals(player, current.player)))
		{
			closed = close();
		}
		if (current == null)
		{
			current = new Session(now, player);
		}
		live = true;
		lastTick = now;
		current.lastSeenAt = now;
		return closed;
	}

	/** Counts play time; called every game tick while logged in. */
	public void tick(long now)
	{
		if (!isLive())
		{
			return;
		}
		long gap = now - lastTick;
		if (gap > 0)
		{
			current.playedMs += Math.min(gap, MAX_TICK_GAP_MS);
		}
		lastTick = now;
		current.lastSeenAt = now;
	}

	/** The player left the game; the session stays open in case they come back. */
	public void pause(long now)
	{
		tick(now);
		live = false;
	}

	/** Closes the paused session once the player has been away for longer than the gap. */
	public Session expire(long now, long gapMs)
	{
		if (current == null || live || now - current.lastSeenAt <= gapMs)
		{
			return null;
		}
		return close();
	}

	/** Ends the session now. Returns it, or null when nothing happened in it. */
	public Session close()
	{
		Session session = current;
		current = null;
		live = false;
		if (session == null)
		{
			return null;
		}
		session.endedAt = session.lastSeenAt;
		return session.isEmpty() ? null : session;
	}

	/**
	 * The player's experience in a skill. The first reading of a session is its starting point;
	 * later readings are progress, and a higher level becomes a moment.
	 */
	public List<Moment> xp(String skill, long xp, int level, long now)
	{
		if (current == null || xp < 0)
		{
			return Collections.emptyList();
		}
		Session.SkillLine line = current.skills.get(skill);
		if (line == null)
		{
			current.skills.put(skill, new Session.SkillLine(skill, xp, level));
			return Collections.emptyList();
		}
		if (xp < line.xp)
		{
			// Experience never falls; a lower reading means the client was not ready yet.
			return Collections.emptyList();
		}
		line.xp = xp;
		List<Moment> moments = new ArrayList<>();
		if (level > line.level)
		{
			int from = line.level;
			line.level = level;
			Moment m;
			if (level == 99)
			{
				m = new Moment(Moment.Kind.MAX, now, "99 " + skill, "The highest level there is", 0, 0);
			}
			else
			{
				String detail = level - from > 1 ? "Up from " + from + ", " + (level - from) + " levels at once" : "Up from " + from;
				m = new Moment(Moment.Kind.LEVEL, now, skill + " level " + level, detail, 0, 0);
			}
			add(m);
			moments.add(m);
		}
		return moments;
	}

	/**
	 * The player came back to a session they had paused. Experience gained while they were
	 * away (on another device) is not this session's, so the starting point moves up with it
	 * and the rates stay honest. Also used after the game hands back stats it swapped out for a
	 * minigame, so the swap never counts as progress.
	 */
	public void resume(String skill, long xp, int level)
	{
		if (current == null || xp < 0)
		{
			return;
		}
		Session.SkillLine line = current.skills.get(skill);
		if (line == null)
		{
			current.skills.put(skill, new Session.SkillLine(skill, xp, level));
			return;
		}
		if (xp == 0 && line.xp > 0)
		{
			return;
		}
		long gained = line.gained();
		int levels = Math.max(0, line.level - line.startLevel);
		line.xp = xp;
		line.startXp = Math.max(0, xp - gained);
		line.level = level;
		line.startLevel = Math.max(1, level - levels);
	}

	/**
	 * Loot from a kill, a raid, a chest or a clue.
	 *
	 * @param source what it came from, such as "Vorkath" or "Chambers of Xeric"
	 * @param kills how many kills or clears it stands for; 0 for loot that is not a kill
	 * @param valuable a single stack worth at least this becomes a moment
	 * @return the moments the loot made
	 */
	public List<Moment> loot(String source, List<Session.Drop> drops, int kills, long valuable, long now)
	{
		if (current == null)
		{
			return Collections.emptyList();
		}
		if (kills > 0 && source != null && !source.isEmpty())
		{
			kill(source).looted += kills;
		}
		List<Moment> moments = new ArrayList<>();
		for (Session.Drop drop : drops)
		{
			if (drop.quantity <= 0)
			{
				continue;
			}
			Session.Drop held = current.loot.get(drop.id);
			if (held == null)
			{
				current.loot.put(drop.id, new Session.Drop(drop.id, drop.name, drop.quantity, drop.price));
			}
			else
			{
				held.quantity += drop.quantity;
				if (drop.price > 0)
				{
					held.price = drop.price;
				}
			}
			if (valuable > 0 && drop.value() >= valuable)
			{
				String name = drop.quantity > 1 ? drop.quantity + " x " + drop.getName() : drop.getName();
				String from = source == null || source.isEmpty() ? "" : source + ", ";
				Moment logged = recent(Moment.Kind.COLLECTION, drop.getName(), now);
				if (logged != null)
				{
					// The log slot was announced first (a raid chest); the drop gives it a picture and a worth.
					logged.itemId = drop.id;
					logged.value = drop.value();
					logged.detail = "New log slot, " + from + coins(drop.value());
					moments.add(logged);
					continue;
				}
				Moment m = new Moment(Moment.Kind.DROP, now, name, from + "worth " + coins(drop.value()), drop.id, drop.value());
				add(m);
				moments.add(m);
			}
		}
		return moments;
	}

	/** The game's own kill count after a kill. */
	public void killCount(String name, int count)
	{
		if (current == null || count <= 0)
		{
			return;
		}
		Session.KillLine line = kill(name);
		String counter = name.toLowerCase(Locale.ROOT).trim();
		if (line.counters == null)
		{
			line.counters = new LinkedHashMap<>();
			if (line.firstKc > 0)
			{
				// Saved before counters were kept apart: that one counter was most likely this one.
				line.counters.put(counter, new int[]{line.firstKc, line.lastKc});
			}
		}
		int[] range = line.counters.get(counter);
		if (range == null)
		{
			range = new int[]{count, count};
			line.counters.put(counter, range);
		}
		range[0] = Math.min(range[0], count);
		range[1] = Math.max(range[1], count);
		if (line.firstKc <= 0 || count < line.firstKc)
		{
			line.firstKc = count;
		}
		line.lastKc = range[1];
	}

	public void moment(Moment moment)
	{
		if (current == null || moment == null)
		{
			return;
		}
		if (moment.getKind() == Moment.Kind.COLLECTION)
		{
			Moment drop = recent(Moment.Kind.DROP, moment.getTitle(), moment.getAt());
			if (drop != null)
			{
				// The same item as a big drop a moment ago: one moment that says both.
				drop.kind = Moment.Kind.COLLECTION;
				drop.title = moment.getTitle();
				drop.detail = "New log slot, " + (drop.detail == null ? "" : drop.detail.replace("worth ", ""));
				return;
			}
		}
		add(moment);
	}

	/** The latest moment of a kind about an item, if it happened within the merge window. */
	private Moment recent(Moment.Kind kind, String item, long now)
	{
		List<Moment> moments = current.moments;
		for (int i = moments.size() - 1; i >= 0 && i >= moments.size() - 12; i--)
		{
			Moment m = moments.get(i);
			if (now - m.getAt() > MERGE_MS)
			{
				break;
			}
			String title = m.getTitle();
			if (m.getKind() == kind && (title.equals(item) || title.endsWith(" x " + item)))
			{
				return m;
			}
		}
		return null;
	}

	/**
	 * The player died.
	 *
	 * @param killer what they were fighting, or null
	 */
	public void death(long now, String killer)
	{
		if (current == null)
		{
			return;
		}
		current.deaths++;
		String detail = killer == null || killer.isEmpty() ? "Back to the respawn point" : "Killed by " + killer;
		add(new Moment(Moment.Kind.DEATH, now, "Oh dear, you are dead", detail, 0, 0));
	}

	private void add(Moment moment)
	{
		List<Moment> moments = current.moments;
		moments.add(moment);
		if (moments.size() > MAX_MOMENTS)
		{
			// Let the least telling moment go, never the newest.
			int drop = 0;
			for (int i = 1; i < moments.size() - 1; i++)
			{
				if (moments.get(i).rank() < moments.get(drop).rank())
				{
					drop = i;
				}
			}
			moments.remove(drop);
		}
	}

	private Session.KillLine kill(String name)
	{
		String key = key(name);
		Session.KillLine line = current.kills.get(key);
		if (line == null)
		{
			line = new Session.KillLine(name);
			current.kills.put(key, line);
		}
		return line;
	}

	/**
	 * Loot and kill count messages name the same boss slightly differently ("The Nightmare" and
	 * "Nightmare", "Barrows" and "Barrows chest", "Tombs of Amascut" and "Tombs of Amascut: Expert
	 * Mode", "Chambers of Xeric Challenge Mode" and "Chambers of Xeric", Dusk and the Grotesque
	 * Guardians); this folds them together so a kill counts once.
	 */
	static String key(String name)
	{
		String key = name.toLowerCase(Locale.ROOT).trim();
		int colon = key.indexOf(':');
		if (colon > 0)
		{
			key = key.substring(0, colon).trim();
		}
		if (key.endsWith(" challenge mode"))
		{
			// The Loot Tracker files a challenge mode chest as plain "Chambers of Xeric".
			key = key.substring(0, key.length() - 15);
		}
		if (key.startsWith("the "))
		{
			key = key.substring(4);
		}
		if (key.endsWith(" chest"))
		{
			key = key.substring(0, key.length() - 6);
		}
		if (key.equals("dusk") || key.equals("dawn"))
		{
			key = "grotesque guardians";
		}
		return key;
	}

	/** "950", "41k", "1.2M": a number short enough for a headline. */
	static String amount(long n)
	{
		return n < 1_000 ? String.valueOf(n) : coins(n);
	}

	static String coins(long gp)
	{
		if (gp >= 1_000_000_000)
		{
			return String.format(Locale.ROOT, "%.2fB", gp / 1e9);
		}
		if (gp >= 1_000_000)
		{
			return String.format(Locale.ROOT, "%.1fM", gp / 1e6);
		}
		if (gp >= 1_000)
		{
			return Math.round(gp / 1e3) + "k";
		}
		return gp + " coins";
	}
}

package com.codex.sessionchronicle.core;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The sessions already lived, newest first, and the records they hold. Sessions are trimmed
 * as they are filed so a long journal still fits comfortably in the RuneLite profile.
 */
public final class Journal
{
	static final int KEEP_DROPS = 24;
	static final int KEEP_KILLS = 12;
	static final int KEEP_MOMENTS = 30;
	static final long WEEK_MS = 7 * 24 * 3_600_000L;

	private Journal()
	{
	}

	/** Files a finished session at the front of the journal, keeping at most cap sessions. */
	public static List<Session> file(List<Session> journal, Session session, int cap)
	{
		List<Session> next = new ArrayList<>();
		next.add(compact(session));
		for (Session s : journal)
		{
			if (s.startedAt != session.startedAt)
			{
				next.add(s);
			}
		}
		next.sort(Comparator.comparingLong(Session::getStartedAt).reversed());
		while (next.size() > Math.max(1, cap))
		{
			next.remove(next.size() - 1);
		}
		return next;
	}

	/** The journal without the session that started at that moment. */
	public static List<Session> remove(List<Session> journal, long startedAt)
	{
		List<Session> next = new ArrayList<>(journal);
		next.removeIf(s -> s.startedAt == startedAt);
		return next;
	}

	/** A copy of the session with only what the journal needs to tell it again. */
	static Session compact(Session s)
	{
		Session c = new Session();
		c.startedAt = s.startedAt;
		c.lastSeenAt = s.lastSeenAt;
		c.endedAt = s.endedAt > 0 ? s.endedAt : s.lastSeenAt;
		c.playedMs = s.playedMs;
		c.player = s.player;
		c.deaths = s.deaths;
		for (Map.Entry<String, Session.SkillLine> e : s.skills.entrySet())
		{
			if (e.getValue().gained() > 0)
			{
				c.skills.put(e.getKey(), e.getValue());
			}
		}
		List<Session.Drop> drops = new ArrayList<>(s.loot.values());
		drops.sort(Comparator.comparingLong(Session.Drop::value).reversed());
		c.otherLoot = s.otherLoot;
		c.otherDrops = s.otherDrops;
		for (int i = 0; i < drops.size(); i++)
		{
			Session.Drop d = drops.get(i);
			if (i < KEEP_DROPS)
			{
				c.loot.put(d.id, d);
			}
			else
			{
				c.otherLoot += d.value();
				c.otherDrops++;
			}
		}
		List<Map.Entry<String, Session.KillLine>> kills = new ArrayList<>(s.kills.entrySet());
		kills.sort(Comparator.comparingInt((Map.Entry<String, Session.KillLine> e) -> e.getValue().count()).reversed());
		Map<String, Session.KillLine> keptKills = new LinkedHashMap<>();
		for (int i = 0; i < kills.size() && i < KEEP_KILLS; i++)
		{
			keptKills.put(kills.get(i).getKey(), kills.get(i).getValue());
		}
		c.kills = keptKills;
		List<Moment> moments = new ArrayList<>(s.moments);
		moments.sort(Comparator.comparingDouble(Moment::rank).reversed());
		if (moments.size() > KEEP_MOMENTS)
		{
			moments = new ArrayList<>(moments.subList(0, KEEP_MOMENTS));
		}
		moments.sort(Comparator.comparingLong(Moment::getAt));
		c.moments = moments;
		return c;
	}

	/** The journal's records and recent rhythm. */
	public static final class Records
	{
		private Session mostXp;
		private Session mostLoot;
		private Session longest;
		private long weekPlayedMs;
		private int weekSessions;
		private int streakDays;

		public Session getMostXp()
		{
			return mostXp;
		}

		public Session getMostLoot()
		{
			return mostLoot;
		}

		public Session getLongest()
		{
			return longest;
		}

		public long getWeekPlayedMs()
		{
			return weekPlayedMs;
		}

		public int getWeekSessions()
		{
			return weekSessions;
		}

		/** Days in a row, up to today or yesterday, with at least one session. */
		public int getStreakDays()
		{
			return streakDays;
		}
	}

	/**
	 * Records across the journal and the session being lived, if any.
	 */
	public static Records records(List<Session> journal, Session current, long now, ZoneId zone)
	{
		List<Session> all = new ArrayList<>(journal);
		if (current != null && !current.isEmpty())
		{
			all.add(current);
		}
		Records r = new Records();
		Set<LocalDate> days = new HashSet<>();
		for (Session s : all)
		{
			if (r.mostXp == null || s.totalXp() > r.mostXp.totalXp())
			{
				r.mostXp = s;
			}
			if (r.mostLoot == null || s.lootValue() > r.mostLoot.lootValue())
			{
				r.mostLoot = s;
			}
			if (r.longest == null || s.playedMs > r.longest.playedMs)
			{
				r.longest = s;
			}
			if (now - s.startedAt <= WEEK_MS)
			{
				r.weekPlayedMs += s.playedMs;
				r.weekSessions++;
			}
			days.add(Instant.ofEpochMilli(s.startedAt).atZone(zone).toLocalDate());
		}
		if (r.mostXp != null && r.mostXp.totalXp() <= 0)
		{
			r.mostXp = null;
		}
		if (r.mostLoot != null && r.mostLoot.lootValue() <= 0)
		{
			r.mostLoot = null;
		}
		LocalDate day = Instant.ofEpochMilli(now).atZone(zone).toLocalDate();
		if (!days.contains(day))
		{
			day = day.minusDays(1);
		}
		while (days.contains(day))
		{
			r.streakDays++;
			day = day.minusDays(1);
		}
		return r;
	}
}

package com.codex.sessionchronicle.core;

/** Something worth remembering from a session: a level, a pet, a big drop, a new log slot. */
public class Moment
{
	/** What kind of moment it is; the order is how much it matters on a card. */
	public enum Kind
	{
		PET(120),
		MAX(100),
		COLLECTION(80),
		DROP(70),
		QUEST(60),
		DIARY(55),
		BEST(50),
		TASK(40),
		LEVEL(30),
		CLUE(20),
		DEATH(10);

		private final int weight;

		Kind(int weight)
		{
			this.weight = weight;
		}

		public int getWeight()
		{
			return weight;
		}
	}

	Kind kind;
	long at;
	String title;
	String detail;
	int itemId;
	long value;

	Moment()
	{
	}

	public Moment(Kind kind, long at, String title, String detail, int itemId, long value)
	{
		this.kind = kind;
		this.at = at;
		this.title = title;
		this.detail = detail;
		this.itemId = itemId;
		this.value = value;
	}

	public Kind getKind()
	{
		return kind == null ? Kind.LEVEL : kind;
	}

	public long getAt()
	{
		return at;
	}

	public String getTitle()
	{
		return title == null ? "" : title;
	}

	public String getDetail()
	{
		return detail;
	}

	public int getItemId()
	{
		return itemId;
	}

	public long getValue()
	{
		return value;
	}

	/** How much the moment matters when only a few fit: its kind, then a big drop's size. */
	double rank()
	{
		double bonus = value > 0 ? Math.min(19, Math.log10(value) * 3) : 0;
		return getKind().getWeight() + bonus;
	}
}

package com.codex.sessionchronicle.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * One play session as it was lived: the experience each skill gained, the loot that dropped,
 * the kills, and the moments worth telling. Plain fields so it saves to the profile as JSON.
 */
public class Session
{
	long startedAt;
	long lastSeenAt;
	long endedAt;
	long playedMs;
	String player;
	Map<String, SkillLine> skills = new LinkedHashMap<>();
	Map<Integer, Drop> loot = new LinkedHashMap<>();
	Map<String, KillLine> kills = new LinkedHashMap<>();
	List<Moment> moments = new ArrayList<>();
	int deaths;
	/** Loot trimmed from the session when it was filed in the journal, so the totals still add up. */
	long otherLoot;
	int otherDrops;

	Session()
	{
	}

	Session(long now, String player)
	{
		startedAt = now;
		lastSeenAt = now;
		this.player = player;
	}

	public long getStartedAt()
	{
		return startedAt;
	}

	public long getLastSeenAt()
	{
		return lastSeenAt;
	}

	public long getEndedAt()
	{
		return endedAt;
	}

	public long getPlayedMs()
	{
		return playedMs;
	}

	public String getPlayer()
	{
		return player;
	}

	public int getDeaths()
	{
		return deaths;
	}

	public long totalXp()
	{
		long total = 0;
		for (SkillLine line : skills.values())
		{
			total += line.gained();
		}
		return total;
	}

	public long lootValue()
	{
		long total = otherLoot;
		for (Drop drop : loot.values())
		{
			total += drop.value();
		}
		return total;
	}

	public int levelsGained()
	{
		int total = 0;
		for (SkillLine line : skills.values())
		{
			total += Math.max(0, line.level - line.startLevel);
		}
		return total;
	}

	public int totalKills()
	{
		int total = 0;
		for (KillLine line : kills.values())
		{
			total += line.count();
		}
		return total;
	}

	/** A session with nothing in it is not worth a page in the journal. */
	boolean isEmpty()
	{
		return totalXp() <= 0 && loot.isEmpty() && kills.isEmpty() && moments.isEmpty() && playedMs < 5 * 60_000L;
	}

	/** Experience in one skill. */
	public static class SkillLine
	{
		String skill;
		long startXp;
		long xp;
		int startLevel;
		int level;

		SkillLine()
		{
		}

		SkillLine(String skill, long xp, int level)
		{
			this.skill = skill;
			this.startXp = xp;
			this.xp = xp;
			this.startLevel = level;
			this.level = level;
		}

		public String getSkill()
		{
			return skill;
		}

		public long gained()
		{
			return Math.max(0, xp - startXp);
		}

		public int getStartLevel()
		{
			return startLevel;
		}

		public int getLevel()
		{
			return level;
		}
	}

	/** One kind of item received, with what it was worth when it dropped. */
	public static class Drop
	{
		int id;
		String name;
		long quantity;
		long price;

		Drop()
		{
		}

		public Drop(int id, String name, long quantity, long price)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
			this.price = price;
		}

		public int getId()
		{
			return id;
		}

		public String getName()
		{
			return name == null ? "Item" : name;
		}

		public long getQuantity()
		{
			return quantity;
		}

		public long getPrice()
		{
			return price;
		}

		public long value()
		{
			return quantity * price;
		}
	}

	/**
	 * Kills of one monster, or clears of one raid or chest. Counted from loot and from the
	 * game's own kill count messages, whichever saw more.
	 */
	public static class KillLine
	{
		String name;
		int looted;
		int firstKc;
		int lastKc;
		/**
		 * The first and last count of each counter the game keeps for it, by the name it gave:
		 * entry and expert Tombs of Amascut, or normal and challenge mode Chambers, count apart.
		 * Null in sessions saved before it, which kept one counter in firstKc and lastKc.
		 */
		Map<String, int[]> counters;

		KillLine()
		{
		}

		KillLine(String name)
		{
			this.name = name;
		}

		public String getName()
		{
			return name;
		}

		public int count()
		{
			int counted = 0;
			if (counters != null)
			{
				for (int[] range : counters.values())
				{
					counted += range[1] - range[0] + 1;
				}
			}
			else if (firstKc > 0)
			{
				counted = lastKc - firstKc + 1;
			}
			return Math.max(looted, counted);
		}

		/** The game's kill count after the latest kill, or 0 if the game never said. */
		public int getKillCount()
		{
			return lastKc;
		}
	}
}

package com.codex.sessionchronicle.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * A read-only telling of one session, ready for the panel and the card: totals, rates, the
 * skills, drops and kills in order of size, its moments and a headline.
 */
public final class Summary
{
	/** Rates are only shown once a session is long enough for them to mean something. */
	static final long MIN_RATE_MS = 5 * 60_000L;
	private static final Pattern CLUE = Pattern.compile("(?i)clue scroll \\((\\w+)\\)");
	/** Raids and other runs that are finished rather than killed. */
	private static final String[] CLEARS = {"chambers of xeric", "theatre of blood", "tombs of amascut", "gauntlet", "corrupted gauntlet",
		"fortis colosseum", "tzhaar-ket-rak", "hallowed sepulchre"};

	private static final List<String> COMBAT = Arrays.asList("Attack", "Strength", "Defence", "Ranged", "Magic",
		"Hitpoints", "Prayer", "Slayer");

	public enum State
	{
		LIVE,
		PAUSED,
		ENDED
	}

	private final State state;
	private final String player;
	private final long startedAt;
	private final long endedAt;
	private final long playedMs;
	private final long totalXp;
	private final long lootValue;
	private final int levels;
	private final int kills;
	private final int deaths;
	private final int otherDrops;
	private final List<Session.SkillLine> skills;
	private final List<Session.Drop> drops;
	private final List<Session.KillLine> killLines;
	private final List<Moment> moments;
	private final List<Moment> highlights;

	private Summary(Session s, State state)
	{
		this.state = state;
		player = s.player;
		startedAt = s.startedAt;
		endedAt = s.endedAt > 0 ? s.endedAt : s.lastSeenAt;
		playedMs = s.playedMs;
		totalXp = s.totalXp();
		lootValue = s.lootValue();
		levels = s.levelsGained();
		kills = s.totalKills();
		deaths = s.deaths;
		otherDrops = s.otherDrops;

		List<Session.SkillLine> skillList = new ArrayList<>();
		for (Session.SkillLine line : s.skills.values())
		{
			if (line.gained() > 0)
			{
				skillList.add(line);
			}
		}
		skillList.sort(Comparator.comparingLong(Session.SkillLine::gained).reversed());
		skills = Collections.unmodifiableList(skillList);

		List<Session.Drop> dropList = new ArrayList<>(s.loot.values());
		dropList.sort(Comparator.comparingLong(Session.Drop::value).reversed()
			.thenComparing(Comparator.comparingLong(Session.Drop::getQuantity).reversed()));
		drops = Collections.unmodifiableList(dropList);

		List<Session.KillLine> killList = new ArrayList<>();
		for (Session.KillLine line : s.kills.values())
		{
			if (line.count() > 0)
			{
				killList.add(line);
			}
		}
		killList.sort(Comparator.comparingInt(Session.KillLine::count).reversed());
		killLines = Collections.unmodifiableList(killList);

		List<Moment> momentList = new ArrayList<>(s.moments);
		momentList.sort(Comparator.comparingLong(Moment::getAt));
		moments = Collections.unmodifiableList(momentList);

		List<Moment> best = new ArrayList<>(s.moments);
		best.sort(Comparator.comparingDouble(Moment::rank).reversed().thenComparingLong(Moment::getAt));
		highlights = Collections.unmodifiableList(best);
	}

	public static Summary of(Session session, State state)
	{
		return new Summary(session, state);
	}

	/** A short fingerprint of everything the panel draws, to tell when a summary has really changed. */
	public static String signature(Summary s)
	{
		if (s == null)
		{
			return "none";
		}
		return s.state + "/" + s.startedAt + "/" + s.playedMs / 60_000 + "/" + s.totalXp + "/" + s.lootValue + "/" + s.kills
			+ "/" + s.levels + "/" + s.deaths + "/" + s.moments.size() + "/" + s.drops.size() + "/" + s.player;
	}

	public State getState()
	{
		return state;
	}

	public String getPlayer()
	{
		return player;
	}

	public long getStartedAt()
	{
		return startedAt;
	}

	public long getEndedAt()
	{
		return endedAt;
	}

	public long getPlayedMs()
	{
		return playedMs;
	}

	public long getTotalXp()
	{
		return totalXp;
	}

	public long getLootValue()
	{
		return lootValue;
	}

	public int getLevels()
	{
		return levels;
	}

	public int getKills()
	{
		return kills;
	}

	public int getDeaths()
	{
		return deaths;
	}

	/** Kinds of item left out of a session filed in the journal; their worth is still in the total. */
	public int getOtherDrops()
	{
		return otherDrops;
	}

	/** Skills that gained experience, most first. */
	public List<Session.SkillLine> getSkills()
	{
		return skills;
	}

	/** Every kind of item received, most valuable first. */
	public List<Session.Drop> getDrops()
	{
		return drops;
	}

	/** What was killed or cleared, most first. */
	public List<Session.KillLine> getKillLines()
	{
		return killLines;
	}

	/** Moments in the order they happened. */
	public List<Moment> getMoments()
	{
		return moments;
	}

	/** Moments in the order they matter. */
	public List<Moment> getHighlights()
	{
		return highlights;
	}

	public long xpPerHour()
	{
		return perHour(totalXp);
	}

	public long lootPerHour()
	{
		return perHour(lootValue);
	}

	private long perHour(long value)
	{
		return playedMs < MIN_RATE_MS ? 0 : Math.round(value * 3_600_000.0 / playedMs);
	}

	/**
	 * One line that says what the session was about, the rarest thing first: a pet, a 99, a new
	 * collection log slot, a boss trip, a run of levels, a slayer grind, then the main skill.
	 */
	public String headline()
	{
		Moment max = null;
		List<Moment> logged = new ArrayList<>();
		for (Moment m : highlights)
		{
			if (m.getKind() == Moment.Kind.PET)
			{
				return "A pet followed you home";
			}
			if (m.getKind() == Moment.Kind.MAX && max == null)
			{
				max = m;
			}
			if (m.getKind() == Moment.Kind.COLLECTION)
			{
				logged.add(m);
			}
		}
		if (max != null)
		{
			return max.getTitle() + "!";
		}
		if (logged.size() == 1)
		{
			return logged.get(0).getTitle() + "!";
		}
		if (logged.size() > 1)
		{
			return logged.size() + " new collection log slots";
		}
		Session.KillLine boss = null;
		for (Session.KillLine line : killLines)
		{
			if (line.getKillCount() > 0)
			{
				boss = line;
				break;
			}
		}
		if (boss != null && boss.count() >= 3)
		{
			return kills(boss);
		}
		Session.SkillLine top = skills.isEmpty() ? null : skills.get(0);
		int gained = top == null ? 0 : top.getLevel() - top.getStartLevel();
		if (gained >= 2)
		{
			return gained + " " + top.getSkill() + " levels";
		}
		// A slayer grind outranks its combat levels; bird nests, crates and reward pools are loot of
		// a skilling session and never outrank the skill.
		if (!killLines.isEmpty() && killLines.get(0).count() >= 10 && (top == null || COMBAT.contains(top.getSkill())))
		{
			return kills(killLines.get(0));
		}
		if (top != null)
		{
			if (gained == 1)
			{
				return top.getSkill() + " level " + top.getLevel();
			}
			long rate = perHour(top.gained());
			return rate > 0 ? top.getSkill() + " at " + Chronicle.amount(rate) + "/hr" : "+" + Chronicle.amount(top.gained()) + " " + top.getSkill() + " xp";
		}
		if (!killLines.isEmpty())
		{
			return kills(killLines.get(0));
		}
		if (lootValue > 0)
		{
			return "A haul worth " + Chronicle.coins(lootValue);
		}
		return "A quiet session";
	}

	/** "24 Vorkath kills", "3 Chambers of Xeric clears", "12 medium clues": what the count stands for. */
	static String kills(Session.KillLine line)
	{
		int n = line.count();
		String name = line.getName();
		Matcher clue = CLUE.matcher(name);
		if (clue.matches())
		{
			return n + " " + clue.group(1).toLowerCase(Locale.ROOT) + (n == 1 ? " clue" : " clues");
		}
		String key = Chronicle.key(name);
		for (String raid : CLEARS)
		{
			if (key.startsWith(raid))
			{
				return n + " " + name + (n == 1 ? " clear" : " clears");
			}
		}
		return n + " " + name + (n == 1 ? " kill" : " kills");
	}
}

package com.codex.sessionchronicle.overlay;

import com.codex.sessionchronicle.ui.Format;
import com.codex.sessionchronicle.ui.Sigil;
import com.codex.sessionchronicle.ui.Theme;
import com.codex.sessionchronicle.ui.Ui;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A slim gilt plaque in the game view with the session's clock, experience and loot. It draws
 * a view the plugin prepares, and runs the clock on from it, so rendering never touches game state.
 */
public class SessionTicker extends Overlay
{
	private static final int PAD = 7;

	/** What the ticker shows. */
	public static final class View
	{
		final long playedMs;
		final long at;
		final boolean live;
		final long xp;
		final long loot;

		public View(long playedMs, long at, boolean live, long xp, long loot)
		{
			this.playedMs = playedMs;
			this.at = at;
			this.live = live;
			this.xp = xp;
			this.loot = loot;
		}
	}

	private volatile View view;
	private volatile boolean enabled;

	public SessionTicker()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	public void show(View view)
	{
		this.view = view;
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		View v = view;
		if (!enabled || v == null)
		{
			return null;
		}
		Theme.smooth(g);
		long played = v.playedMs + (v.live ? Math.max(0, Math.min(5_000, System.currentTimeMillis() - v.at)) : 0);
		String clock = Format.clock(played);
		String xp = Format.xp(v.xp) + " xp";
		String loot = Format.coins(v.loot) + " gp";

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int icon = 14;
		int gap = 10;
		int width = PAD + icon + 6 + bold.stringWidth(clock) + gap + small.stringWidth(xp) + gap + small.stringWidth(loot) + PAD;
		int height = Math.max(icon, bold.getHeight()) + PAD;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, width - 1, height - 1, 10, 10);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 230), 0, height, Theme.alpha(Theme.INK_DEEP, 230)));
		g.fill(shape);
		g.setColor(Theme.alpha(Theme.GOLD, 170));
		g.draw(shape);

		int x = PAD;
		Sigil.paint(g, x, (height - icon) / 2f, icon);
		x += icon + 6;
		int base = (height + bold.getAscent()) / 2 - 2;
		g.setFont(Theme.title());
		Ui.shadowed(g, clock, x, base, v.live ? Theme.TEXT : Theme.TEXT_MUTED);
		x += bold.stringWidth(clock) + gap;
		g.setFont(Theme.small());
		Ui.shadowed(g, xp, x, base, Theme.XP);
		x += small.stringWidth(xp) + gap;
		Ui.shadowed(g, loot, x, base, Theme.LOOT);
		return new Dimension(width, height);
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Recent sessions as a row of bars, oldest on the left. The tallest is gilded, hovering names
 * a bar and clicking opens that session.
 */
class BarChart extends JComponent
{
	private static final int LABEL_H = 14;

	/** One bar. */
	static final class Bar
	{
		final String label;
		final String tip;
		final long value;

		Bar(String label, String tip, long value)
		{
			this.label = label;
			this.tip = tip;
			this.value = value;
		}
	}

	private final List<Bar> bars;
	private final Color color;
	private int hover = -1;

	BarChart(List<Bar> bars, Color color, IntConsumer onClick)
	{
		this.bars = bars;
		this.color = color;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 92));
		setToolTipText("");
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index >= 0 && onClick != null)
				{
					onClick.accept(index);
				}
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private int indexAt(int x)
	{
		if (bars.isEmpty())
		{
			return -1;
		}
		int index = x * bars.size() / Math.max(1, getWidth());
		return index >= 0 && index < bars.size() ? index : -1;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		int index = indexAt(e.getX());
		return index < 0 ? null : bars.get(index).tip;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight() - LABEL_H;
		long max = 1;
		int best = -1;
		for (int i = 0; i < bars.size(); i++)
		{
			if (bars.get(i).value > max)
			{
				max = bars.get(i).value;
				best = i;
			}
		}

		// Faint guide lines at the half and the top.
		g.setColor(Theme.alpha(Theme.STROKE_SOFT, 160));
		g.drawLine(0, 4, w, 4);
		g.drawLine(0, 4 + (h - 4) / 2, w, 4 + (h - 4) / 2);
		g.setColor(Theme.STROKE);
		g.drawLine(0, h, w, h);

		float slot = w / (float) Math.max(1, bars.size());
		float bw = Math.max(3, Math.min(16, slot - 4));
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < bars.size(); i++)
		{
			Bar bar = bars.get(i);
			float x = i * slot + (slot - bw) / 2;
			float bh = bar.value <= 0 ? 0 : Math.max(3, (h - 6) * bar.value / (float) max);
			Color c = i == best ? Theme.GOLD_BRIGHT : color;
			if (i == hover)
			{
				g.setColor(Theme.alpha(Theme.GOLD, 26));
				g.fillRect(Math.round(i * slot), 0, Math.round(slot), h);
			}
			if (bh > 0)
			{
				RoundRectangle2D shape = new RoundRectangle2D.Float(x, h - bh, bw, bh + 3, 4, 4);
				g.setClip(0, 0, w, h);
				g.setPaint(new GradientPaint(0, h - bh, c, 0, h, Theme.mix(c, Theme.INK, 0.55)));
				g.fill(shape);
				g.setColor(Theme.alpha(java.awt.Color.WHITE, 50));
				g.drawLine(Math.round(x + 1), Math.round(h - bh + 1), Math.round(x + bw - 2), Math.round(h - bh + 1));
				g.setClip(null);
			}
			if (bars.size() <= 14 || i % 2 == bars.size() % 2)
			{
				String label = bar.label;
				g.setColor(i == hover ? Theme.TEXT : Theme.TEXT_FAINT);
				g.drawString(label, Math.round(i * slot + (slot - fm.stringWidth(label)) / 2), getHeight() - 2);
			}
		}
		g.dispose();
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

