package com.codex.sessionchronicle.ui;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** The card shrunk to the panel's width, smoothly, with a soft shadow under it. */
class CardPreview extends JComponent
{
	private final BufferedImage card;
	private Image scaled;
	private int scaledWidth;

	CardPreview(BufferedImage card)
	{
		this.card = card;
		setOpaque(false);
		setPreferredSize(new Dimension(SessionView.WIDTH, SessionView.WIDTH * card.getHeight() / card.getWidth() + 4));
		setToolTipText("Your session card, as it will be saved");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		// Fit the card inside the box, whichever of width or height runs out first.
		int w = Math.min(getWidth() - 2, (getHeight() - 4) * card.getWidth() / card.getHeight());
		if (w <= 0)
		{
			g.dispose();
			return;
		}
		int left = (getWidth() - w) / 2;
		if (scaled == null || scaledWidth != w)
		{
			scaled = shrink(card, w);
			scaledWidth = w;
		}
		g.setColor(Theme.alpha(java.awt.Color.BLACK, 90));
		g.fillRoundRect(left + 2, 4, w - 2, scaled.getHeight(null) - 2, 10, 10);
		g.drawImage(scaled, left, 0, null);
		g.dispose();
	}

	/** Halves the image step by step so the shrunk card keeps its detail. */
	private static Image shrink(BufferedImage image, int width)
	{
		BufferedImage current = image;
		while (current.getWidth() / 2 >= width)
		{
			current = resize(current, current.getWidth() / 2);
		}
		return current.getWidth() == width ? current : resize(current, width);
	}

	private static BufferedImage resize(BufferedImage image, int width)
	{
		int height = Math.max(1, image.getHeight() * width / image.getWidth());
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.drawImage(image, 0, 0, width, height, null);
		g.dispose();
		return out;
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Journal;
import com.codex.sessionchronicle.core.Summary;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Session Chronicle side panel: the crest, then three pages. Session is the session being
 * lived (or one opened from the journal), Journal is every session kept with its records, and
 * Card is the session as a picture to save or copy.
 */
public class ChroniclePanel extends PluginPanel
{
	private static final String[] TABS = {"session", "journal", "card"};

	private final ItemIcons items;
	private final Icons icons;
	private final CardActions actions;
	private final SessionActions sessionActions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Session", "Journal", "Card");
	private final Segmented metrics = new Segmented(false, JournalView.METRICS);
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane session = scroller();
	private final JScrollPane journal = scroller();
	private final JScrollPane card = scroller();

	private Summary live;
	private List<Summary> past = Collections.emptyList();
	private Journal.Records records;
	private String playerName;
	private boolean showName = true;
	private int open = -1;
	private int tab;
	private String cardNote;
	private BufferedImage cardImage;
	/** Set when data arrived while the panel was closed; it is drawn once the panel opens. */
	private boolean stale;
	/** What the Session and Card tabs last drew, so an unchanged session is not built again. */
	private String sessionDrawn;
	private String cardDrawn;

	public ChroniclePanel(ItemIcons items, Icons icons, CardActions actions, SessionActions sessionActions)
	{
		super(false);
		this.items = items;
		this.icons = icons;
		this.actions = actions;
		this.sessionActions = sessionActions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(session, TABS[0]);
		content.add(journal, TABS[1]);
		content.add(card, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		metrics.onChange(i -> rebuildJournal());
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/**
	 * Called on the Swing thread whenever the chronicle changes.
	 *
	 * @param live the session being lived, or null
	 * @param past finished sessions, newest first
	 */
	public void update(Summary live, List<Summary> past, Journal.Records records, String playerName)
	{
		boolean journalChanged = past != this.past;
		if (journalChanged && open >= 0)
		{
			// The journal moved under the open session; find it again by when it started.
			long started = this.past.get(open).getStartedAt();
			open = -1;
			for (int i = 0; i < past.size(); i++)
			{
				if (past.get(i).getStartedAt() == started)
				{
					open = i;
				}
			}
		}
		this.live = live;
		this.past = past;
		this.records = records;
		this.playerName = playerName;
		if (!isShowing())
		{
			// Nothing is drawn while the panel is closed; it catches up when it opens.
			stale = true;
			return;
		}
		refresh(journalChanged || stale);
	}

	@Override
	public void onActivate()
	{
		if (stale)
		{
			refresh(true);
		}
	}

	private void refresh(boolean journalChanged)
	{
		stale = false;
		crest.update(shown(), playerName);
		if (open < 0)
		{
			rebuildSession(false);
		}
		if (journalChanged)
		{
			rebuildJournal();
		}
		if (tab == 2)
		{
			rebuildCard(false);
		}
	}

	/** Builds the Session tab again, unless what it shows has not changed. */
	private void rebuildSession(boolean force)
	{
		Summary s = shown();
		String drawn = (open >= 0 ? "past:" : "live:") + Summary.signature(s);
		if (!force && drawn.equals(sessionDrawn))
		{
			return;
		}
		sessionDrawn = drawn;
		replace(session, open >= 0 ? SessionView.build(s, items, icons, this::backToLive, this::removeOpen, null)
			: SessionView.build(s, items, icons, null, null, sessionActions::endSession));
	}

	private void removeOpen()
	{
		if (open >= 0 && open < past.size())
		{
			sessionActions.removeSession(past.get(open).getStartedAt());
			backToLive();
		}
	}

	public void setShowName(boolean showName)
	{
		this.showName = showName;
		if (tab == 2)
		{
			rebuildCard(true);
		}
	}

	/** A line under the card's buttons, such as where it was saved. */
	public void cardNote(String note)
	{
		cardNote = note;
		rebuildCard(true);
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int index)
	{
		tab = index;
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
		if (index == 2)
		{
			cardNote = null;
			rebuildCard(true);
		}
	}

	/** Opens a session from the journal on the Session tab. */
	public void openPast(int index)
	{
		if (index < 0 || index >= past.size())
		{
			return;
		}
		open = index;
		crest.update(shown(), playerName);
		rebuildSession(true);
		showTab(0);
		SwingUtilities.invokeLater(() -> session.getVerticalScrollBar().setValue(0));
	}

	private void backToLive()
	{
		open = -1;
		crest.update(shown(), playerName);
		rebuildSession(true);
	}

	private Summary shown()
	{
		return open >= 0 && open < past.size() ? past.get(open) : live;
	}

	private void rebuild()
	{
		crest.update(shown(), playerName);
		rebuildSession(true);
		rebuildJournal();
	}

	private void rebuildJournal()
	{
		if (records == null)
		{
			replace(journal, SessionView.note("The journal is empty", "Sessions are filed here as they end."));
			return;
		}
		replace(journal, JournalView.build(past, records, metrics, this::openPast));
	}

	private void rebuildCard(boolean force)
	{
		Summary s = shown();
		if (s == null && !past.isEmpty())
		{
			s = past.get(0);
		}
		// The card is a large picture; only paint it again when the session on it has moved on.
		String drawn = s == null ? "none" : showName + "/" + s.getState() + "/" + s.getStartedAt() + "/" + s.getPlayedMs() / 60_000
			+ "/" + Format.xp(s.getTotalXp()) + "/" + Format.coins(s.getLootValue()) + "/" + s.getKills() + "/" + s.getLevels()
			+ "/" + s.getMoments().size() + "/" + s.getDrops().size() + "/" + s.getDeaths() + "/" + open;
		if (!force && drawn.equals(cardDrawn))
		{
			return;
		}
		cardDrawn = drawn;
		StackPanel stack = new StackPanel(8, 8);
		if (s == null)
		{
			stack.add(SessionView.note("Nothing to share yet", "Once your session has some experience, loot or kills in it, its card appears here, ready to save or copy."));
			replace(card, stack);
			return;
		}
		Summary shownSession = s;
		cardImage = ShareCard.render(s, showName, items, icons, () -> SwingUtilities.invokeLater(this::refreshCardImage));
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.CENTER, 6, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Save card", true, () -> actions.save(cardImage, shownSession)));
		buttons.add(new CodexButton("Copy to clipboard", false, () -> actions.copy(cardImage)));
		stack.add(new SectionHeader(open >= 0 ? "From the journal" : s.getState() == Summary.State.LIVE ? "Live session" : "Last session",
			Format.day(s.getStartedAt())));
		stack.add(new CardPreview(cardImage));
		stack.add(buttons);
		String note = cardNote != null ? cardNote : "Save card asks where to put the picture. Copy puts it on the clipboard, ready to paste.";
		stack.add(Ui.wrapped(note, Theme.small(), cardNote != null ? Theme.TEAL : Theme.TEXT_FAINT, SessionView.WIDTH - 10));
		replace(card, stack);
	}

	private boolean refreshPending;

	/** Item pictures arrive after the first render; redraw once they are in. */
	private void refreshCardImage()
	{
		if (refreshPending || tab != 2)
		{
			return;
		}
		refreshPending = true;
		SwingUtilities.invokeLater(() ->
		{
			refreshPending = false;
			rebuildCard(true);
		});
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;
import javax.swing.Timer;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	/** How long a button that asks for a second click waits for it. */
	private static final int CONFIRM_MS = 3_000;

	private String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;
	private Color warn;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		size(text);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	/**
	 * A quiet button for something that cannot be undone: the first click asks again in its own
	 * label, and only a second click within a few seconds does it.
	 */
	public static CodexButton confirming(String text, String confirm, Runnable action)
	{
		CodexButton[] self = new CodexButton[1];
		Timer reset = new Timer(CONFIRM_MS, e -> self[0].arm(null, text));
		reset.setRepeats(false);
		self[0] = new CodexButton(text, false, () ->
		{
			if (self[0].warn == null)
			{
				self[0].arm(Theme.BLOOD, confirm);
				reset.restart();
			}
			else
			{
				reset.stop();
				self[0].arm(null, text);
				action.run();
			}
		});
		// Keep the button the width of its longer label so the row does not jump.
		FontMetrics fm = self[0].getFontMetrics(self[0].getFont());
		self[0].size(fm.stringWidth(confirm) > fm.stringWidth(text) ? confirm : text);
		return self[0];
	}

	private void arm(Color color, String label)
	{
		warn = color;
		text = label;
		repaint();
	}

	private void size(String widest)
	{
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(widest) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			Color tint = warn != null ? warn : Theme.GOLD;
			g.setColor(hover ? Theme.alpha(tint, 40) : Theme.alpha(tint, 14));
			g.fill(shape);
			text = warn != null ? Theme.mix(warn, Theme.TEXT, 0.35) : hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(warn != null ? warn : Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Summary;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.geom.Path2D;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The crest at the top of the panel: the session clock, the player, and ledgers for experience, loot and kills. */
public class Crest extends JPanel
{
	private final SessionClock clock = new SessionClock(74);
	private final JLabel title = Ui.label("Session Chronicle", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel subtitle = Ui.label("Log in to begin a session", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger xp = new Ledger("Experience");
	private final Ledger loot = new Ledger("Loot");
	private final Ledger kills = new Ledger("Kills");
	private Color glow = Theme.GOLD_DIM;

	public Crest()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel clockHolder = new JPanel(new BorderLayout());
		clockHolder.setOpaque(false);
		clockHolder.add(clock, BorderLayout.NORTH);
		add(clockHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		title.setAlignmentX(LEFT_ALIGNMENT);
		subtitle.setAlignmentX(LEFT_ALIGNMENT);
		right.add(title);
		right.add(subtitle);
		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(xp);
		ledgers.add(loot);
		ledgers.add(kills);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
		update(null, null);
	}

	/** Shows a session, or the waiting state when there is none. */
	public void update(Summary s, String playerName)
	{
		title.setText(playerName != null ? playerName : s != null && s.getPlayer() != null ? s.getPlayer() : "Session Chronicle");
		if (s == null)
		{
			subtitle.setText(playerName == null ? "Log in to begin a session" : "Beginning your session...");
			subtitle.setForeground(Theme.TEXT_MUTED);
			clock.set(0, "", Theme.TEXT_MUTED, false);
			xp.set("-", Theme.TEXT);
			loot.set("-", Theme.TEXT);
			kills.set("-", Theme.TEXT);
			glow = Theme.GOLD_DIM;
			repaint();
			return;
		}
		Color state;
		String caption;
		switch (s.getState())
		{
			case LIVE:
				state = Theme.GREEN;
				caption = "LIVE";
				subtitle.setText("Live since " + Format.time(s.getStartedAt()));
				break;
			case PAUSED:
				state = Theme.GOLD;
				caption = "PAUSED";
				subtitle.setText("Paused at " + Format.time(s.getEndedAt()));
				break;
			default:
				state = Theme.TEXT_MUTED;
				caption = "ENDED";
				subtitle.setText("From " + Format.day(s.getStartedAt()));
				break;
		}
		subtitle.setForeground(Theme.mix(Theme.TEXT_MUTED, state, 0.35));
		clock.set(s.getPlayedMs(), caption, state, true);
		xp.set(s.getTotalXp() > 0 ? Format.xp(s.getTotalXp()) : "-", Theme.XP);
		loot.set(s.getLootValue() > 0 ? Format.coins(s.getLootValue()) : "-", Theme.LOOT);
		kills.set(s.getKills() > 0 ? String.valueOf(s.getKills()) : "-", Theme.KILLS);
		glow = Theme.mix(Theme.GOLD_DIM, state, 0.3);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, glow, 0.2), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** One labelled value. */
	private static final class Ledger extends JPanel
	{
		private final JLabel value = Ui.label("-", Theme.small(), Theme.TEXT);

		Ledger(String label)
		{
			super(new BorderLayout());
			setOpaque(false);
			add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
			add(value, BorderLayout.EAST);
			setPreferredSize(new Dimension(10, 15));
		}

		void set(String text, Color color)
		{
			value.setText(text);
			value.setForeground(color);
		}
	}
}

package com.codex.sessionchronicle.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Experience, coins, durations and dates in the short forms the panel and the card use. */
public final class Format
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter FILE = DateTimeFormatter.ofPattern("yyyy-MM-dd HH-mm", Locale.ENGLISH);

	private Format()
	{
	}

	/** "8,240", "41.2k", "412k", "1.24M". */
	public static String amount(long n)
	{
		if (n < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", n);
		}
		if (n < 100_000)
		{
			return trim(n / 1_000.0, 1) + "k";
		}
		if (n < 1_000_000)
		{
			return Math.round(n / 1_000.0) + "k";
		}
		if (n < 10_000_000)
		{
			return trim(n / 1_000_000.0, 2) + "M";
		}
		if (n < 1_000_000_000)
		{
			return trim(n / 1_000_000.0, 1) + "M";
		}
		return trim(n / 1_000_000_000.0, 2) + "B";
	}

	/** Gained experience with its sign: "+412k". */
	public static String xp(long xp)
	{
		return "+" + amount(Math.max(0, xp));
	}

	public static String coins(long gp)
	{
		return amount(Math.max(0, gp));
	}

	private static String trim(double value, int places)
	{
		String text = String.format(Locale.ENGLISH, "%." + places + "f", value);
		while (text.contains(".") && (text.endsWith("0") || text.endsWith(".")))
		{
			text = text.substring(0, text.length() - 1);
		}
		return text;
	}

	/** "312k/hr", or "" when there is no rate yet. */
	public static String rate(long perHour)
	{
		return perHour <= 0 ? "" : amount(perHour) + "/hr";
	}

	/** "2h 14m", "38m", "under a minute". */
	public static String duration(long ms)
	{
		long minutes = ms / 60_000;
		if (minutes < 1)
		{
			return "under a minute";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		return minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** "1:42" for a session clock. */
	public static String clock(long ms)
	{
		long minutes = ms / 60_000;
		return minutes / 60 + ":" + String.format(Locale.ENGLISH, "%02d", minutes % 60);
	}

	/** "14:02" in the player's own time. */
	public static String time(long epochMs)
	{
		return CLOCK.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct". */
	public static String day(long epochMs)
	{
		return DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "16", the day of the month, for a chart's labels. */
	public static String dayOfMonth(long epochMs)
	{
		return String.valueOf(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()).getDayOfMonth());
	}

	/** "Thursday 16 October 2026". */
	public static String date(long epochMs)
	{
		return DATE.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "2026-10-16 14-02", safe in a file name. */
	public static String file(long epochMs)
	{
		return FILE.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** An item stack the way the game writes it: "950", "45K", "12M". */
	public static String stack(long n)
	{
		if (n < 100_000)
		{
			return String.valueOf(n);
		}
		if (n < 10_000_000)
		{
			return n / 1_000 + "K";
		}
		return n / 1_000_000 + "M";
	}

	/** The colour the game writes a stack of that size in. */
	public static java.awt.Color stackColor(long n)
	{
		return n < 100_000 ? Theme.QTY_YELLOW : n < 10_000_000 ? Theme.QTY_WHITE : Theme.QTY_GREEN;
	}
}

