package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Journal;
import com.codex.sessionchronicle.core.Session;
import com.codex.sessionchronicle.core.Summary;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The Journal tab: records, a chart of recent sessions and every session kept, newest first. */
final class JournalView
{
	static final String[] METRICS = {"Experience", "Loot", "Time"};
	private static final int CHART = 14;

	private JournalView()
	{
	}

	/**
	 * @param sessions finished sessions, newest first
	 * @param open called with an index into sessions to open one
	 */
	static JComponent build(List<Summary> sessions, Journal.Records records, Segmented metrics, IntConsumer open)
	{
		StackPanel stack = new StackPanel(8, 8);
		JPanel tiles = new JPanel(new GridLayout(2, 2, 6, 6));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.duration(records.getWeekPlayedMs()).replace("under a minute", "0m"), "This week",
			records.getWeekSessions() + (records.getWeekSessions() == 1 ? " session" : " sessions"), Theme.TEAL));
		int streak = records.getStreakDays();
		tiles.add(new StatTile(streak == 0 ? "-" : streak + (streak == 1 ? " day" : " days"), "Streak",
			streak > 1 ? "in a row" : streak == 1 ? "play tomorrow too" : "no play yesterday", Theme.EMBER));
		Session xp = records.getMostXp();
		tiles.add(new StatTile(xp == null ? "-" : Format.xp(xp.totalXp()), "Most XP", xp == null ? "" : Format.day(xp.getStartedAt()), Theme.XP));
		Session loot = records.getMostLoot();
		tiles.add(new StatTile(loot == null ? "-" : Format.coins(loot.lootValue()), "Most loot", loot == null ? "" : Format.day(loot.getStartedAt()), Theme.LOOT));
		stack.add(tiles);

		if (sessions.isEmpty())
		{
			stack.add(SessionView.note("The journal is empty", "Each session is filed here when it ends: when you log out and stay away longer than the break allowance in the settings."));
			return stack;
		}

		int metric = metrics.getSelected();
		stack.add(new SectionHeader("Recent sessions", "last " + Math.min(CHART, sessions.size())));
		stack.add(metrics);
		List<BarChart.Bar> bars = new ArrayList<>();
		int count = Math.min(CHART, sessions.size());
		for (int i = count - 1; i >= 0; i--)
		{
			Summary s = sessions.get(i);
			long value = metric == 0 ? s.getTotalXp() : metric == 1 ? s.getLootValue() : s.getPlayedMs();
			String shown = metric == 0 ? Format.xp(value) + " xp" : metric == 1 ? Format.coins(value) + " loot" : Format.duration(value);
			String label = Format.dayOfMonth(s.getStartedAt());
			bars.add(new BarChart.Bar(label, Format.day(s.getStartedAt()) + ", " + Format.time(s.getStartedAt()) + ": " + shown, value));
		}
		Color color = metric == 0 ? Theme.XP : metric == 1 ? Theme.LOOT : Theme.EMBER;
		stack.add(new BarChart(bars, color, index -> open.accept(count - 1 - index)));

		stack.add(new SectionHeader("Sessions", String.valueOf(sessions.size())));
		for (int i = 0; i < sessions.size(); i++)
		{
			int index = i;
			stack.add(row(sessions.get(i)).onClick(() -> open.accept(index)));
		}
		return stack;
	}

	private static Card row(Summary s)
	{
		Card card = new Card(new BorderLayout(0, 2));
		card.accent(s.getLootValue() > s.getTotalXp() / 10 ? Theme.LOOT : Theme.XP);
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(Ui.label(Format.day(s.getStartedAt()) + ", " + Format.time(s.getStartedAt()), Theme.small(), Theme.GOLD), BorderLayout.WEST);
		top.add(Ui.label(Format.duration(s.getPlayedMs()), Theme.small(), Theme.TEXT_MUTED), BorderLayout.EAST);
		card.add(top, BorderLayout.NORTH);
		card.add(Ui.label(s.headline(), Theme.body(), Theme.TEXT), BorderLayout.CENTER);
		JPanel bottom = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		bottom.setOpaque(false);
		// Only what the session has: a skilling session shows no empty loot and kill columns.
		if (s.getTotalXp() > 0)
		{
			bottom.add(value(Format.xp(s.getTotalXp()) + " xp", Theme.XP));
		}
		if (s.getLootValue() > 0)
		{
			bottom.add(value(Format.coins(s.getLootValue()) + " gp", Theme.LOOT));
		}
		if (s.getKills() > 0)
		{
			bottom.add(value(s.getKills() + (s.getKills() == 1 ? " kill" : " kills"), Theme.KILLS));
		}
		if (bottom.getComponentCount() == 0)
		{
			bottom.add(value("Nothing gained", Theme.TEXT_FAINT));
		}
		card.add(bottom, BorderLayout.SOUTH);
		return card;
	}

	private static JLabel value(String text, Color color)
	{
		JLabel label = Ui.label(text, Theme.small(), color);
		label.setBorder(new EmptyBorder(0, 0, 0, 10));
		return label;
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Session;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** One monster, raid or chest: how many this session and the game's kill count after them. */
class KillRow extends JComponent
{
	private final Session.KillLine line;
	private final double share;

	KillRow(Session.KillLine line, double share)
	{
		this.line = line;
		this.share = share;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 18));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, line, share, 0, 0, getWidth());
		g.dispose();
	}

	static void paint(Graphics2D g, Session.KillLine line, double share, int x, int y, int w)
	{
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int base = y + fm.getAscent();
		Path2D mark = new Path2D.Float();
		float my = base - fm.getAscent() / 2f + 1;
		mark.moveTo(x + 3, my - 3);
		mark.lineTo(x + 6, my);
		mark.lineTo(x + 3, my + 3);
		mark.lineTo(x, my);
		mark.closePath();
		g.setColor(Theme.mix(Theme.GOLD_DIM, Theme.KILLS, Math.max(0.2, share)));
		g.fill(mark);

		String count = "x" + line.count();
		String kc = line.getKillCount() > 0 ? "KC " + String.format("%,d", line.getKillCount()) : "";
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int kcw = kc.isEmpty() ? 0 : small.stringWidth(kc) + 8;
		g.setFont(Theme.body());
		int cw = fm.stringWidth(count);
		Ui.shadowed(g, count, x + w - kcw - cw, base, Theme.KILLS);
		Ui.shadowed(g, Ui.clip(line.getName(), fm, w - kcw - cw - 18), x + 12, base, Theme.TEXT);
		if (!kc.isEmpty())
		{
			g.setFont(Theme.small());
			Ui.shadowed(g, kc, x + w - kcw + 8, base, Theme.TEXT_FAINT);
		}
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Moment;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * One stop on the session's timeline: the time, a node on a gilt thread coloured by the kind
 * of moment, and what happened. Consecutive rows join their threads into one line.
 */
class MomentRow extends JComponent
{
	static final int HEIGHT = 34;
	private static final int TIME_W = 34;

	private final Moment moment;
	private final BufferedImage icon;
	private final boolean first;
	private final boolean last;

	MomentRow(Moment moment, BufferedImage icon, boolean first, boolean last)
	{
		this.moment = moment;
		this.icon = icon;
		this.first = first;
		this.last = last;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		String detail = moment.getDetail();
		setToolTipText(detail == null ? moment.getTitle() : moment.getTitle() + ": " + detail);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		Color color = Theme.moment(moment.getKind());
		int nx = TIME_W + 6;
		int ny = 10;

		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 140));
		if (!first)
		{
			g.drawLine(nx, 0, nx, ny);
		}
		if (!last)
		{
			g.drawLine(nx, ny, nx, h);
		}
		node(g, moment.getKind(), nx, ny, color);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Ui.shadowed(g, Format.time(moment.getAt()), 0, ny + small.getAscent() / 2 - 1, Theme.TEXT_FAINT);

		int tx = nx + 10;
		int right = w;
		if (icon != null)
		{
			g.drawImage(icon, w - icon.getWidth(), Math.max(0, (h - icon.getHeight()) / 2 - 2), null);
			right = w - icon.getWidth() - 4;
		}
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(moment.getTitle(), fm, right - tx), tx, ny + fm.getAscent() / 2 - 1, Theme.mix(Theme.TEXT, color, 0.25));
		if (moment.getDetail() != null)
		{
			g.setFont(Theme.small());
			Ui.shadowed(g, Ui.clip(moment.getDetail(), small, right - tx), tx, ny + fm.getAscent() / 2 + small.getHeight(), Theme.TEXT_MUTED);
		}
		g.dispose();
	}

	/** The node: a diamond for most moments, a ringed star for a pet or a 99. Shared with the card. */
	static void node(Graphics2D g, Moment.Kind kind, float x, float y, Color color)
	{
		boolean grand = kind == Moment.Kind.PET || kind == Moment.Kind.MAX;
		if (grand)
		{
			g.setColor(Theme.alpha(color, 60));
			g.fill(new Ellipse2D.Float(x - 7, y - 7, 14, 14));
			g.setColor(Theme.alpha(color, 160));
			g.draw(new Ellipse2D.Float(x - 6, y - 6, 12, 12));
		}
		float r = grand ? 4.5f : 4f;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x, y - r);
		diamond.lineTo(x + r, y);
		diamond.lineTo(x, y + r);
		diamond.lineTo(x - r, y);
		diamond.closePath();
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(x - r - 1.5f, y - r - 1.5f, r * 2 + 3, r * 2 + 3));
		g.setColor(color);
		g.fill(diamond);
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

