package com.codex.sessionchronicle.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import javax.swing.JComponent;

/**
 * The session clock in the crest: the ring fills through each hour played, a gold pip marks
 * every hour already done, and the middle reads the time played and whether it is still live.
 */
public class SessionClock extends JComponent
{
	private final int diameter;
	private final Animator animator = new Animator(this);
	private String text = "-";
	private String caption = "";
	private Color captionColor = Theme.TEXT_MUTED;
	private int hours;

	public SessionClock(int diameter)
	{
		this.diameter = diameter;
		Dimension size = new Dimension(diameter, diameter);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setOpaque(false);
	}

	public void set(long playedMs, String caption, Color captionColor, boolean animate)
	{
		long minutes = playedMs / 60_000;
		hours = (int) (minutes / 60);
		text = playedMs <= 0 && caption.isEmpty() ? "-" : Format.clock(playedMs);
		this.caption = caption;
		this.captionColor = captionColor;
		animator.set((minutes % 60) / 60.0, animate);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		float thickness = 5;
		float inset = thickness / 2f + 3;
		float size = diameter - inset * 2;
		float c = diameter / 2f;

		g.setPaint(new RadialGradientPaint(c, c, size / 2f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(Theme.TEAL, 34), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(inset, inset, size, size));

		// Minute ticks around the outside, longer on the quarters.
		g.setStroke(new BasicStroke(1f));
		for (int i = 0; i < 60; i += 5)
		{
			double a = Math.toRadians(i * 6 - 90);
			float outer = diameter / 2f - 0.5f;
			float inner = outer - (i % 15 == 0 ? 3.5f : 2f);
			g.setColor(Theme.alpha(Theme.GOLD_DIM, i % 15 == 0 ? 200 : 120));
			g.draw(new Line2D.Double(c + Math.cos(a) * inner, c + Math.sin(a) * inner, c + Math.cos(a) * outer, c + Math.sin(a) * outer));
		}

		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.STROKE, 200));
		g.draw(new Arc2D.Float(inset, inset, size, size, 0, 360, Arc2D.OPEN));
		double value = animator.get();
		if (value > 0)
		{
			g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			int segments = Math.max(1, (int) Math.ceil(value * 72));
			double sweep = value * 360 / segments;
			for (int i = 0; i < segments; i++)
			{
				double t = (i + 1) / (double) segments * value;
				g.setColor(Theme.mix(Theme.TEAL, Theme.GOLD_BRIGHT, t));
				g.draw(new Arc2D.Double(inset, inset, size, size, 90 - i * sweep, -sweep - (i < segments - 1 ? 0.6 : 0), Arc2D.OPEN));
			}
		}

		// One pip for each whole hour, in an arc across the top of the well.
		int pips = Math.min(hours, 12);
		float pr = size / 2f - thickness - 3;
		for (int i = 0; i < pips; i++)
		{
			double a = Math.toRadians(-90 + (i - (pips - 1) / 2.0) * 13);
			float px = (float) (c + Math.cos(a) * pr);
			float py = (float) (c + Math.sin(a) * pr);
			g.setColor(Theme.alpha(Theme.GOLD, 70));
			g.fill(new Ellipse2D.Float(px - 2.5f, py - 2.5f, 5, 5));
			g.setColor(Theme.GOLD_BRIGHT);
			g.fill(new Ellipse2D.Float(px - 1.5f, py - 1.5f, 3, 3));
		}

		g.setFont(Theme.title());
		FontMetrics fm = g.getFontMetrics();
		int textY = diameter / 2 + fm.getAscent() / 2 - 4;
		Ui.shadowed(g, text, (diameter - fm.stringWidth(text)) / 2, textY, Theme.TEXT);
		if (!caption.isEmpty())
		{
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			Ui.shadowed(g, caption, (diameter - small.stringWidth(caption)) / 2, textY + small.getAscent() + 1, captionColor);
		}
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 90));
		g.draw(new Ellipse2D.Float(0.5f, 0.5f, diameter - 1, diameter - 1));
		g.dispose();
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Moment;
import com.codex.sessionchronicle.core.Session;
import com.codex.sessionchronicle.core.Summary;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

/** The Session tab: the session's headline and totals, then its skills, loot, kills and moments. */
final class SessionView
{
	static final int WIDTH = 200;
	private static final int SKILLS = 8;
	private static final int DROPS = 20;
	private static final int KILLS = 8;

	private SessionView()
	{
	}

	/**
	 * @param backToLive shown as a button when an older session is open; null for the live one
	 * @param remove takes the open older session out of the journal; null for the live one
	 * @param end closes the live session now; null for an older one
	 */
	static JComponent build(Summary s, ItemIcons items, Icons icons, Runnable backToLive, Runnable remove, Runnable end)
	{
		StackPanel stack = new StackPanel(8, 8);
		if (backToLive != null)
		{
			Card banner = new Card(new BorderLayout(0, 6));
			banner.accent(Theme.GOLD_DIM);
			banner.add(Ui.label("From the journal", Theme.small(), Theme.TEXT_MUTED), BorderLayout.NORTH);
			JPanel buttons = new JPanel(new BorderLayout(6, 0));
			buttons.setOpaque(false);
			buttons.add(new CodexButton("Back to live", false, backToLive), BorderLayout.WEST);
			if (remove != null)
			{
				buttons.add(CodexButton.confirming("Remove", "Remove it?", remove), BorderLayout.EAST);
			}
			banner.add(buttons, BorderLayout.CENTER);
			stack.add(banner);
		}
		if (s == null)
		{
			stack.add(note("No session yet", "Log in and Session Chronicle starts writing. Every skill you train, every drop and every kill lands here, and the whole session can be saved as a card to share."));
			return stack;
		}

		Card head = new Card(new BorderLayout());
		head.highlighted(true);
		JPanel lines = new JPanel();
		lines.setOpaque(false);
		lines.setLayout(new BoxLayout(lines, BoxLayout.Y_AXIS));
		JLabel headline = Ui.label(s.headline(), Theme.title(), Theme.GOLD_BRIGHT);
		lines.add(headline);
		lines.add(Ui.label(Format.duration(s.getPlayedMs()) + " played, " + Format.time(s.getStartedAt()) + " to "
			+ (s.getState() == Summary.State.LIVE ? "now" : Format.time(s.getEndedAt())), Theme.small(), Theme.TEXT_MUTED));
		head.add(lines, BorderLayout.CENTER);
		stack.add(head);

		JPanel tiles = new JPanel(new GridLayout(2, 2, 6, 6));
		tiles.setOpaque(false);
		tiles.add(new StatTile(s.getTotalXp() > 0 ? Format.xp(s.getTotalXp()) : "0", "Experience", Format.rate(s.xpPerHour()), Theme.XP));
		tiles.add(new StatTile(Format.coins(s.getLootValue()), "Loot", Format.rate(s.lootPerHour()), Theme.LOOT));
		Session.SkillLine levelled = null;
		for (Session.SkillLine line : s.getSkills())
		{
			if (line.getLevel() > line.getStartLevel() && (levelled == null || line.getLevel() - line.getStartLevel() > levelled.getLevel() - levelled.getStartLevel()))
			{
				levelled = line;
			}
		}
		tiles.add(new StatTile("+" + s.getLevels(), "Levels", levelled == null ? "none this time" : levelled.getSkill() + " " + levelled.getLevel(), Theme.GREEN));
		List<Session.KillLine> killLines = s.getKillLines();
		tiles.add(new StatTile(String.valueOf(s.getKills()), "Kills", killLines.isEmpty() ? "" : killLines.get(0).getName(), Theme.KILLS));
		stack.add(tiles);

		List<Session.SkillLine> skills = s.getSkills();
		if (!skills.isEmpty())
		{
			stack.add(new SectionHeader("Experience", Format.rate(s.xpPerHour())));
			long top = skills.get(0).gained();
			for (int i = 0; i < skills.size() && i < SKILLS; i++)
			{
				Session.SkillLine line = skills.get(i);
				long rate = s.getPlayedMs() < 5 * 60_000L ? 0 : Math.round(line.gained() * 3_600_000.0 / s.getPlayedMs());
				stack.add(new SkillRow(line, icons == null ? null : icons.skill(line.getSkill()), line.gained() / (double) top, rate));
			}
			if (skills.size() > SKILLS)
			{
				stack.add(Ui.label("and " + (skills.size() - SKILLS) + " more skills", Theme.small(), Theme.TEXT_FAINT));
			}
		}

		List<Session.Drop> drops = s.getDrops();
		if (!drops.isEmpty())
		{
			stack.add(new SectionHeader("Loot", Format.coins(s.getLootValue())));
			stack.add(new ItemGrid(drops.subList(0, Math.min(DROPS, drops.size())), items, 5));
			int more = drops.size() - DROPS + s.getOtherDrops();
			if (more > 0)
			{
				stack.add(Ui.label("and " + more + " more kinds of item", Theme.small(), Theme.TEXT_FAINT));
			}
		}

		if (!killLines.isEmpty())
		{
			stack.add(new SectionHeader("Kills", String.valueOf(s.getKills())));
			int top = killLines.get(0).count();
			for (int i = 0; i < killLines.size() && i < KILLS; i++)
			{
				stack.add(new KillRow(killLines.get(i), killLines.get(i).count() / (double) top));
			}
		}

		List<Moment> moments = s.getMoments();
		if (!moments.isEmpty())
		{
			stack.add(new SectionHeader("Moments", String.valueOf(moments.size())));
			JPanel timeline = new JPanel(new GridLayout(0, 1, 0, 0));
			timeline.setOpaque(false);
			for (int i = 0; i < moments.size(); i++)
			{
				Moment m = moments.get(i);
				BufferedImage icon = m.getItemId() > 0 && items != null ? items.icon(m.getItemId(), timeline::repaint) : null;
				timeline.add(new MomentRow(m, icon, i == 0, i == moments.size() - 1));
			}
			stack.add(timeline);
		}

		if (end != null && s.getState() != Summary.State.ENDED)
		{
			stack.space(4);
			JPanel row = new JPanel(new BorderLayout(8, 0));
			row.setOpaque(false);
			row.add(Ui.wrapped("Changing activity? File this session now.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 90),
				BorderLayout.CENTER);
			JPanel holder = new JPanel(new BorderLayout());
			holder.setOpaque(false);
			holder.add(CodexButton.confirming("End session", "End it now?", end), BorderLayout.NORTH);
			row.add(holder, BorderLayout.EAST);
			stack.add(row);
		}
		return stack;
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Moment;
import com.codex.sessionchronicle.core.Session;
import com.codex.sessionchronicle.core.Summary;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * The shareable card: one session told on a gilt-framed page, drawn at twice the panel's scale
 * so the game's pixel fonts stay crisp when it is posted anywhere.
 */
public final class ShareCard
{
	static final int WIDTH = 360;
	static final int SCALE = 2;
	private static final int PAD = 20;
	private static final int SKILLS = 5;
	private static final int DROPS = 16;
	private static final int COLUMNS = 8;
	private static final int KILLS = 4;
	private static final int HIGHLIGHTS = 3;

	private ShareCard()
	{
	}

	/** Renders the card; icons still loading are left out and onLoaded runs when one arrives. */
	public static BufferedImage render(Summary s, boolean showName, ItemIcons items, Icons skills, Runnable onLoaded)
	{
		// A first pass only measures, so it draws into a single pixel.
		BufferedImage scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = scratch.createGraphics();
		int height = content(sg, s, showName, items, skills, onLoaded);
		sg.dispose();

		BufferedImage image = new BufferedImage(WIDTH * SCALE, height * SCALE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.scale(SCALE, SCALE);
		Theme.smooth(g);
		frame(g, height);
		content(g, s, showName, items, skills, onLoaded);
		g.dispose();
		return image;
	}

	private static void frame(Graphics2D g, int h)
	{
		int w = WIDTH;
		RoundRectangle2D page = new RoundRectangle2D.Float(0, 0, w, h, 18, 18);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.CARD_TOP, 0.5), 0, h, Theme.INK_DEEP));
		g.fill(page);
		g.setClip(page);
		g.setPaint(new RadialGradientPaint(w / 2f, 40, w * 0.8f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(Theme.GOLD, 46), Theme.alpha(Theme.GOLD, 0)}));
		g.fillRect(0, 0, w, h);

		// A faint grain, the same every time, so the page reads as vellum rather than a flat fill.
		Random grain = new Random(7);
		for (int i = 0; i < w * h / 26; i++)
		{
			g.setColor(Theme.alpha(grain.nextBoolean() ? Theme.GOLD_BRIGHT : Color.BLACK, 6 + grain.nextInt(8)));
			g.fillRect(grain.nextInt(w), grain.nextInt(h), 1, 1);
		}
		g.setClip(null);

		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 190));
		g.draw(new RoundRectangle2D.Float(4.5f, 4.5f, w - 9, h - 9, 14, 14));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 120));
		g.draw(new RoundRectangle2D.Float(8.5f, 8.5f, w - 17, h - 17, 10, 10));
		float[][] corners = {{14, 14}, {w - 14, 14}, {14, h - 14}, {w - 14, h - 14}};
		for (float[] c : corners)
		{
			diamond(g, c[0], c[1], 3.5f, Theme.GOLD);
		}
	}

	/** Lays out and draws everything inside the frame; returns the page height it needs. */
	private static int content(Graphics2D g, Summary s, boolean showName, ItemIcons items, Icons skills, Runnable onLoaded)
	{
		Theme.smooth(g);
		int x = PAD;
		int w = WIDTH - PAD * 2;
		int y = PAD + 4;

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Sigil.paint(g, x, y - 1, 13);
		g.setColor(Theme.GOLD);
		g.drawString("SESSION CHRONICLE", x + 18, y + small.getAscent() - 1);
		String date = Format.date(s.getStartedAt());
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(date, x + w - small.stringWidth(date), y + small.getAscent() - 1);
		y += small.getHeight() + 8;

		boolean named = showName && s.getPlayer() != null;
		String headline = s.headline();
		// The name heads the card; without it the headline takes its place, as large as fits.
		String big = named ? s.getPlayer() : headline;
		Font font = Theme.title();
		for (float scale : new float[]{2f, 1.5f})
		{
			Font scaled = Theme.title().deriveFont(Theme.title().getSize2D() * scale);
			if (named || g.getFontMetrics(scaled).stringWidth(big) <= w)
			{
				font = scaled;
				break;
			}
		}
		g.setFont(font);
		FontMetrics large = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(big, large, w), x, y + large.getAscent() - 4, Theme.GOLD_BRIGHT);
		y += large.getAscent() - 2;
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		if (named)
		{
			Ui.shadowed(g, Ui.clip(headline, bold, w), x, y + bold.getAscent(), Theme.TEXT);
			y += bold.getHeight();
		}
		else
		{
			y += 4;
		}
		g.setFont(Theme.small());
		String when = Format.duration(s.getPlayedMs()) + " played, " + Format.time(s.getStartedAt()) + " to " + Format.time(s.getEndedAt());
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(when, x, y + small.getAscent());
		y += small.getHeight() + 8;
		rule(g, x, y, w);
		y += 10;

		// Experience and loot always; kills and levels when the session has them, levels if it has neither.
		List<String[]> tiles = new ArrayList<>();
		List<Color> colors = new ArrayList<>();
		tiles.add(new String[]{s.getTotalXp() > 0 ? Format.xp(s.getTotalXp()) : "0", "Experience", Format.rate(s.xpPerHour())});
		colors.add(Theme.XP);
		tiles.add(new String[]{Format.coins(s.getLootValue()), "Loot", Format.rate(s.lootPerHour())});
		colors.add(Theme.LOOT);
		if (s.getKills() > 0)
		{
			tiles.add(new String[]{String.valueOf(s.getKills()), "Kills", s.getKillLines().get(0).getName()});
			colors.add(Theme.KILLS);
		}
		if (s.getLevels() > 0 || s.getKills() == 0)
		{
			tiles.add(new String[]{"+" + s.getLevels(), "Levels", topLevel(s)});
			colors.add(Theme.GREEN);
		}
		int tileH = 54;
		int gap = 6;
		int left = x;
		for (int i = 0; i < tiles.size(); i++)
		{
			int tw = i == tiles.size() - 1 ? x + w - left : (w - gap * (tiles.size() - 1)) / tiles.size();
			String[] t = tiles.get(i);
			StatTile.paint(g, t[0], t[1], t[2], colors.get(i), left, y, tw, tileH);
			left += tw + gap;
		}
		y += tileH + 12;

		List<Session.SkillLine> skillLines = s.getSkills();
		if (!skillLines.isEmpty())
		{
			header(g, "Experience", skillLines.size() > SKILLS ? skillLines.size() + " skills" : null, x, y, w);
			y += 24;
			long top = skillLines.get(0).gained();
			for (int i = 0; i < skillLines.size() && i < SKILLS; i++)
			{
				Session.SkillLine line = skillLines.get(i);
				SkillRow.paint(g, line, skills == null ? null : skills.skill(line.getSkill()), line.gained() / (double) top, x, y, w);
				y += 30;
			}
			y += 4;
		}

		List<Session.Drop> drops = s.getDrops();
		if (!drops.isEmpty())
		{
			int more = drops.size() - DROPS + s.getOtherDrops();
			header(g, "Loot", more > 0 ? "+" + more + " more" : null, x, y, w);
			y += 24;
			int slotW = (w - (COLUMNS - 1) * 3) / COLUMNS;
			int shown = Math.min(DROPS, drops.size());
			for (int i = 0; i < shown; i++)
			{
				Session.Drop d = drops.get(i);
				BufferedImage icon = items == null ? null : items.icon(d.getId(), onLoaded);
				ItemGrid.paintSlot(g, x + (i % COLUMNS) * (slotW + 3), y + (i / COLUMNS) * (ItemGrid.SLOT_H + 3), slotW, ItemGrid.SLOT_H,
					icon, d.getQuantity(), d.value());
			}
			y += ((shown + COLUMNS - 1) / COLUMNS) * (ItemGrid.SLOT_H + 3) + 9;
		}

		List<Session.KillLine> kills = s.getKillLines();
		if (!kills.isEmpty())
		{
			header(g, "Kills", null, x, y, w);
			y += 24;
			int top = kills.get(0).count();
			int shown = Math.min(KILLS, kills.size());
			// One line of kills spans the page, so its count sits at the edge like the skills above.
			int colW = shown == 1 ? w : (w - 16) / 2;
			for (int i = 0; i < shown; i++)
			{
				KillRow.paint(g, kills.get(i), kills.get(i).count() / (double) top, x + (i % 2) * (colW + 16), y + (i / 2) * 20, colW);
			}
			y += ((shown + 1) / 2) * 20 + 6;
		}

		List<Moment> highlights = new ArrayList<>(s.getHighlights());
		if (!highlights.isEmpty())
		{
			header(g, "Highlights", null, x, y, w);
			y += 24;
			for (int i = 0; i < highlights.size() && i < HIGHLIGHTS; i++)
			{
				Moment m = highlights.get(i);
				Color color = Theme.moment(m.getKind());
				MomentRow.node(g, m.getKind(), x + 6, y + 7, color);
				int tx = x + 20;
				int right = x + w;
				if (m.getItemId() > 0 && items != null)
				{
					BufferedImage icon = items.icon(m.getItemId(), onLoaded);
					if (icon != null)
					{
						g.drawImage(icon, right - icon.getWidth(), y - 4, null);
						right -= icon.getWidth() + 6;
					}
				}
				g.setFont(Theme.body());
				FontMetrics fm = g.getFontMetrics();
				Ui.shadowed(g, Ui.clip(m.getTitle(), fm, right - tx), tx, y + fm.getAscent() - 2, Theme.mix(Theme.TEXT, color, 0.3));
				if (m.getDetail() != null)
				{
					g.setFont(Theme.small());
					g.setColor(Theme.TEXT_MUTED);
					g.drawString(Ui.clip(m.getDetail(), small, right - tx), tx, y + fm.getAscent() + small.getAscent());
				}
				y += 32;
			}
		}

		y += 2;
		rule(g, x, y, w);
		y += 8;
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("Codex Session Chronicle for RuneLite", x, y + small.getAscent());
		String deaths = s.getDeaths() > 0 ? s.getDeaths() + (s.getDeaths() == 1 ? " death" : " deaths") : "No deaths";
		g.setColor(s.getDeaths() > 0 ? Theme.mix(Theme.TEXT_FAINT, Theme.BLOOD, 0.6) : Theme.TEXT_FAINT);
		g.drawString(deaths, x + w - small.stringWidth(deaths), y + small.getAscent());
		y += small.getHeight();
		return y + PAD;
	}

	/** "Ranged 99": the skill that rose the most, for the levels tile. */
	private static String topLevel(Summary s)
	{
		Session.SkillLine best = null;
		for (Session.SkillLine line : s.getSkills())
		{
			int up = line.getLevel() - line.getStartLevel();
			if (up > 0 && (best == null || up > best.getLevel() - best.getStartLevel()))
			{
				best = line;
			}
		}
		return best == null ? "" : best.getSkill() + " " + best.getLevel();
	}

	private static void header(Graphics2D g, String text, String trailing, int x, int y, int w)
	{
		g.setFont(Theme.small());
		SectionHeader.paint(g, text.toUpperCase(), trailing, x, y, w, 20);
	}

	private static void rule(Graphics2D g, int x, int y, int w)
	{
		g.setStroke(new BasicStroke(1f));
		g.setPaint(new GradientPaint(x, 0, Theme.alpha(Theme.GOLD, 0), x + w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(x, y, x + w, y);
		diamond(g, x + w / 2f, y, 3, Theme.GOLD);
	}

	private static void diamond(Graphics2D g, float cx, float cy, float r, Color color)
	{
		Path2D d = new Path2D.Float();
		d.moveTo(cx, cy - r);
		d.lineTo(cx + r, cy);
		d.lineTo(cx, cy + r);
		d.lineTo(cx - r, cy);
		d.closePath();
		g.setColor(color);
		g.fill(d);
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** Session Chronicle's mark: a gilt quill writing on an unrolled scroll, with a drop of teal ink. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;

		// The scroll: a sheet with a roll at each end.
		RoundRectangle2D sheet = new RoundRectangle2D.Float(x + 2.2f * s, y + 4.4f * s, 10.6f * s, 10 * s, 1.5f * s, 1.5f * s);
		g.setPaint(new GradientPaint(x, y + 4 * s, Theme.mix(Theme.GOLD_BRIGHT, Theme.TEXT, 0.4), x, y + 15 * s, Theme.GOLD_DIM));
		g.fill(sheet);
		g.setColor(Theme.INK_DEEP);
		g.setStroke(new BasicStroke(Math.max(0.7f, 0.6f * s)));
		g.draw(sheet);
		for (float ry : new float[]{4.4f, 14.4f})
		{
			RoundRectangle2D roll = new RoundRectangle2D.Float(x + 1.2f * s, y + (ry - 1.1f) * s, 12.6f * s, 2.2f * s, 2.2f * s, 2.2f * s);
			g.setPaint(new GradientPaint(x, y + (ry - 1.1f) * s, Theme.GOLD_BRIGHT, x, y + (ry + 1.1f) * s, Theme.GOLD_DIM));
			g.fill(roll);
			g.setColor(Theme.INK_DEEP);
			g.draw(roll);
		}

		// Lines of writing.
		g.setStroke(new BasicStroke(Math.max(0.8f, 0.7f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 190));
		float[][] lines = {{4, 7.4f, 10.5f}, {4, 9.6f, 9}, {4, 11.8f, 7.2f}};
		for (float[] l : lines)
		{
			g.drawLine(Math.round(x + l[0] * s), Math.round(y + l[1] * s), Math.round(x + l[2] * s), Math.round(y + l[1] * s));
		}

		// The quill, leaning in from the top right.
		Path2D feather = new Path2D.Float();
		feather.moveTo(x + 8.6f * s, y + 11.8f * s);
		feather.curveTo(x + 10 * s, y + 7 * s, x + 12.5f * s, y + 2.6f * s, x + 15.6f * s, y + 0.4f * s);
		feather.curveTo(x + 15 * s, y + 4 * s, x + 12.6f * s, y + 8.2f * s, x + 8.6f * s, y + 11.8f * s);
		feather.closePath();
		g.setPaint(new GradientPaint(x + 9 * s, y + 12 * s, Theme.GOLD, x + 15 * s, y, Theme.TEXT));
		g.fill(feather);
		g.setColor(Theme.INK_DEEP);
		g.setStroke(new BasicStroke(Math.max(0.6f, 0.5f * s)));
		g.draw(feather);

		// A drop of ink at the nib.
		float r = 1.3f * s;
		g.setColor(Theme.alpha(Theme.TEAL, 100));
		g.fill(new Ellipse2D.Float(x + 8.2f * s - r * 1.6f, y + 12.4f * s - r * 1.6f, r * 3.2f, r * 3.2f));
		g.setColor(Theme.TEAL);
		g.fill(new Ellipse2D.Float(x + 8.2f * s - r, y + 12.4f * s - r, r * 2, r * 2));
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Session;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** One skill's session: its icon and name, the levels it rose through, the experience, and its share of the whole. */
class SkillRow extends JComponent
{
	private final Session.SkillLine line;
	private final BufferedImage icon;
	private final double share;
	private final long perHour;

	SkillRow(Session.SkillLine line, BufferedImage icon, double share, long perHour)
	{
		this.line = line;
		this.icon = icon;
		this.share = share;
		this.perHour = perHour;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 30));
		setToolTipText(line.getSkill() + ": " + String.format("%,d", line.gained()) + " xp" + (perHour > 0 ? ", " + Format.rate(perHour) : ""));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, line, icon, share, 0, 0, getWidth());
		g.dispose();
	}

	/** Draws the row at a place and width; the card uses the same drawing. */
	static void paint(Graphics2D g, Session.SkillLine line, BufferedImage icon, double share, int x, int y, int w)
	{
		int iconBox = 20;
		if (icon != null)
		{
			double scale = Math.min(1, iconBox / (double) Math.max(icon.getWidth(), icon.getHeight()));
			int iw = (int) Math.round(icon.getWidth() * scale);
			int ih = (int) Math.round(icon.getHeight() * scale);
			g.drawImage(icon, x + (iconBox - iw) / 2, y + 2 + (iconBox - ih) / 2, iw, ih, null);
		}
		int tx = x + iconBox + 6;
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int base = y + fm.getAscent() + 1;
		String gained = Format.xp(line.gained());
		int gw = fm.stringWidth(gained);
		Ui.shadowed(g, gained, x + w - gw, base, Theme.XP);
		String levels = line.getLevel() > line.getStartLevel() ? line.getStartLevel() + " > " + line.getLevel() : String.valueOf(line.getLevel());
		int nameRoom = w - (tx - x) - gw - 8;
		String name = Ui.clip(line.getSkill(), fm, nameRoom);
		Ui.shadowed(g, name, tx, base, Theme.TEXT);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int lx = tx + fm.stringWidth(name) + 6;
		if (lx + small.stringWidth(levels) < x + w - gw - 6)
		{
			Ui.shadowed(g, levels, lx, base, line.getLevel() > line.getStartLevel() ? Theme.GREEN : Theme.TEXT_FAINT);
		}

		int by = y + 22;
		int bw = w - (tx - x);
		RoundRectangle2D track = new RoundRectangle2D.Float(tx, by, bw, 4, 4, 4);
		g.setColor(Theme.INK_DEEP);
		g.fill(track);
		float fill = (float) Math.max(4, bw * Math.max(0, Math.min(1, share)));
		g.setPaint(new GradientPaint(tx, 0, Theme.mix(Theme.TEAL, Theme.INK, 0.35), tx + bw, 0, Theme.TEAL));
		g.fill(new RoundRectangle2D.Float(tx, by, fill, 4, 4, 4));
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.sessionchronicle.ui;

import com.codex.sessionchronicle.core.Moment;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Session Chronicle gives experience teal, loot gold and kills ember, so a number's colour
 * says what it counts before it is read.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	public static final Color XP = TEAL;
	public static final Color LOOT = GOLD;
	public static final Color KILLS = EMBER;

	/** The colour of a kind of moment. */
	public static Color moment(Moment.Kind kind)
	{
		switch (kind)
		{
			case PET:
				return VIOLET;
			case MAX:
				return GOLD_BRIGHT;
			case COLLECTION:
				return TEAL;
			case DROP:
				return GOLD;
			case QUEST:
			case DIARY:
			case TASK:
				return new Color(150, 170, 230);
			case BEST:
				return EMBER;
			case LEVEL:
				return GREEN;
			case DEATH:
				return BLOOD;
			default:
				return GOLD_DIM;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.sessionchronicle.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.sessionchronicle.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class ChatParserTest
{
	@Test
	public void readsKillCounts()
	{
		ChatParser.KillCount kc = ChatParser.killCount("Your Vorkath kill count is: 1,412.");
		assertEquals("Vorkath", kc.getName());
		assertEquals(1412, kc.getCount());

		kc = ChatParser.killCount("Your completed Theatre of Blood count is: 25.");
		assertEquals("Theatre of Blood", kc.getName());
		assertEquals(25, kc.getCount());

		kc = ChatParser.killCount("Your Barrows chest count is: 300.");
		assertEquals("Barrows chest", kc.getName());

		kc = ChatParser.killCount("Your Chambers of Xeric count is: 7.");
		assertEquals("Chambers of Xeric", kc.getName());

		assertNull(ChatParser.killCount("You have a funny feeling like you're being followed."));
	}

	@Test
	public void readsMoments()
	{
		Moment m = ChatParser.moment("New item added to your collection log: Draconic visage", 1, null);
		assertEquals(Moment.Kind.COLLECTION, m.getKind());
		assertEquals("Draconic visage", m.getTitle());

		m = ChatParser.moment("You have a funny feeling like you're being followed.", 1, null);
		assertEquals(Moment.Kind.PET, m.getKind());

		m = ChatParser.moment("Congratulations, you've completed a quest: Dragon Slayer II", 1, null);
		assertEquals(Moment.Kind.QUEST, m.getKind());
		assertEquals("Dragon Slayer II", m.getTitle());

		m = ChatParser.moment("Congratulations! You have completed all of the hard tasks in the Varrock area. Speak to Toby to claim your reward.", 1, null);
		assertEquals(Moment.Kind.DIARY, m.getKind());
		assertEquals("Varrock hard diary", m.getTitle());

		m = ChatParser.moment("Congratulations, you've completed an elite combat task: Faithless Crypt Run (5 points).", 1, null);
		assertEquals(Moment.Kind.TASK, m.getKind());
		assertEquals("Faithless Crypt Run", m.getTitle());
		assertEquals("Elite combat task", m.getDetail());

		m = ChatParser.moment("You have completed 12 medium Treasure Trails.", 1, null);
		assertEquals(Moment.Kind.CLUE, m.getKind());
		assertEquals("Medium clue scroll", m.getTitle());

		m = ChatParser.moment("Fight duration: 1:04.20 (new personal best)", 1, "Vorkath");
		assertEquals(Moment.Kind.BEST, m.getKind());
		assertEquals("Vorkath in 1:04.20", m.getTitle());

		m = ChatParser.moment("Theatre of Blood total completion time: 18:30 (new personal best)", 1, null);
		assertEquals("Theatre of Blood in 18:30", m.getTitle());

		assertNull(ChatParser.moment("Welcome to Old School RuneScape.", 1, null));
	}
}

package com.codex.sessionchronicle.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class ChronicleTest
{
	private static final long MIN = 60_000;
	private static final long GAP = 15 * MIN;

	@Test
	public void countsExperienceFromTheFirstReading()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.xp("Slayer", 1_000_000, 80, 0);
		c.xp("Slayer", 1_050_000, 80, 1000);
		assertEquals(50_000, c.current().totalXp());
		// A lower reading is the client catching up, never lost experience.
		c.xp("Slayer", 10, 1, 2000);
		assertEquals(50_000, c.current().totalXp());
	}

	@Test
	public void levelsBecomeMoments()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.xp("Slayer", 1_000_000, 80, 0);
		List<Moment> up = c.xp("Slayer", 1_100_000, 81, 10);
		assertEquals(1, up.size());
		assertEquals("Slayer level 81", up.get(0).getTitle());
		up = c.xp("Slayer", 13_034_431, 99, 20);
		assertEquals(Moment.Kind.MAX, up.get(0).getKind());
		assertEquals(19, c.current().levelsGained());
	}

	@Test
	public void resumesWithinTheBreakAndStartsAfresh()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.xp("Attack", 100, 1, 0);
		c.xp("Attack", 500, 5, 1);
		Session first = c.current();
		c.tick(4000);
		c.pause(8000);
		assertNull(c.begin(8000 + 10 * MIN, "Zezima", GAP));
		assertSame(first, c.current());

		c.pause(8000 + 11 * MIN);
		assertNull(c.expire(8000 + 20 * MIN, GAP));
		Session closed = c.expire(8000 + 30 * MIN, GAP);
		assertSame(first, closed);
		assertEquals(first.getLastSeenAt(), closed.getEndedAt());
		assertNull(c.current());
	}

	@Test
	public void anotherCharacterStartsANewSession()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.loot("Cow", Collections.singletonList(new Session.Drop(526, "Bones", 1, 100)), 1, 0, 0);
		c.pause(MIN);
		Session closed = c.begin(2 * MIN, "Lynx Titan", GAP);
		assertNotNull(closed);
		assertEquals("Lynx Titan", c.current().getPlayer());
	}

	@Test
	public void playTimeIgnoresFrozenClients()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.tick(600);
		c.tick(1200);
		c.tick(60_000);
		assertEquals(1200 + Chronicle.MAX_TICK_GAP_MS, c.current().getPlayedMs());
	}

	@Test
	public void emptySessionsAreNotKept()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.tick(600);
		assertNull(c.close());
	}

	@Test
	public void lootStacksAndValuableDropsStandOut()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		List<Moment> m = c.loot("Vorkath", Arrays.asList(
			new Session.Drop(536, "Dragon bones", 2, 2_500),
			new Session.Drop(11286, "Draconic visage", 1, 4_200_000)), 1, 500_000, 5);
		c.loot("Vorkath", Collections.singletonList(new Session.Drop(536, "Dragon bones", 2, 2_600)), 1, 500_000, 10);
		assertEquals(1, m.size());
		assertEquals("Draconic visage", m.get(0).getTitle());
		assertEquals(4, c.current().loot.get(536).getQuantity());
		assertEquals(4 * 2_600 + 4_200_000, c.current().lootValue());
		assertEquals(2, c.current().totalKills());
	}

	@Test
	public void killCountsAndLootAgreeOnKills()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		for (int kc = 100; kc <= 104; kc++)
		{
			c.loot("Vorkath", Collections.emptyList(), 1, 0, kc);
			c.killCount("Vorkath", kc);
		}
		c.killCount("Barrows chest", 50);
		c.loot("Barrows", Collections.emptyList(), 1, 0, 0);
		c.killCount("Barrows chest", 51);
		Summary s = Summary.of(c.current(), Summary.State.LIVE);
		assertEquals(2, s.getKillLines().size());
		assertEquals(5, s.getKillLines().get(0).count());
		assertEquals(104, s.getKillLines().get(0).getKillCount());
		assertEquals(2, s.getKillLines().get(1).count());
		assertEquals("5 Vorkath kills", s.headline());
	}

	@Test
	public void petsLeadTheHeadline()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.xp("Slayer", 1_000_000, 80, 0);
		c.xp("Slayer", 1_200_000, 82, 0);
		assertEquals("2 Slayer levels", Summary.of(c.current(), Summary.State.LIVE).headline());
		c.moment(ChatParser.moment("You have a funny feeling like you're being followed.", 5, null));
		Summary s = Summary.of(c.current(), Summary.State.LIVE);
		assertEquals("A pet followed you home", s.headline());
		assertEquals(Moment.Kind.PET, s.getHighlights().get(0).getKind());
		assertTrue(s.getMoments().get(0).getAt() <= s.getMoments().get(s.getMoments().size() - 1).getAt());
	}

	@Test
	public void ratesWaitForEnoughTime()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.xp("Mining", 0, 1, 0);
		c.xp("Mining", 10_000, 30, 0);
		for (long t = 600; t <= 2 * MIN; t += 600)
		{
			c.tick(t);
		}
		assertEquals(0, Summary.of(c.current(), Summary.State.LIVE).xpPerHour());
		for (long t = 2 * MIN; t <= 30 * MIN; t += 600)
		{
			c.tick(t);
		}
		assertEquals(20_000, Summary.of(c.current(), Summary.State.LIVE).xpPerHour(), 100);
	}

	@Test
	public void bossNamesFoldTogether()
	{
		assertEquals(Chronicle.key("Nightmare"), Chronicle.key("The Nightmare"));
		assertEquals(Chronicle.key("Tombs of Amascut"), Chronicle.key("Tombs of Amascut: Expert Mode"));
		assertEquals(Chronicle.key("Theatre of Blood"), Chronicle.key("Theatre of Blood: Hard Mode"));
		assertEquals(Chronicle.key("Grotesque Guardians"), Chronicle.key("Dusk"));
		assertEquals(Chronicle.key("Corrupted Gauntlet"), Chronicle.key("The Corrupted Gauntlet"));
		assertEquals(Chronicle.key("Barrows"), Chronicle.key("Barrows chest"));

		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		for (int kc = 10; kc <= 12; kc++)
		{
			c.loot("Dusk", Collections.emptyList(), 1, 0, kc);
			c.killCount("Grotesque Guardians", kc);
		}
		assertEquals(3, c.current().totalKills());
	}

	@Test
	public void aLogSlotAndItsDropAreOneMoment()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.loot("Vorkath", Collections.singletonList(new Session.Drop(11286, "Draconic visage", 1, 4_200_000)), 1, 500_000, 1000);
		c.moment(ChatParser.moment("New item added to your collection log: Draconic visage", 30_000, null));
		assertEquals(1, c.current().moments.size());
		Moment m = c.current().moments.get(0);
		assertEquals(Moment.Kind.COLLECTION, m.getKind());
		assertEquals(11286, m.getItemId());
		assertEquals("New log slot, Vorkath, 4.2M", m.getDetail());

		// A raid announces the slot before the chest's loot arrives.
		c.moment(ChatParser.moment("New item added to your collection log: Twisted bow", 60_000, null));
		c.loot("Chambers of Xeric", Collections.singletonList(new Session.Drop(20997, "Twisted bow", 1, 1_500_000_000)), 1, 500_000, 61_000);
		assertEquals(2, c.current().moments.size());
		assertEquals(20997, c.current().moments.get(1).getItemId());

		// A 99 still leads the highlights over even the richest new slot.
		c.xp("Ranged", 13_000_000, 98, 0);
		c.xp("Ranged", 13_034_431, 99, 62_000);
		assertEquals(Moment.Kind.MAX, Summary.of(c.current(), Summary.State.LIVE).getHighlights().get(0).getKind());

		// Long after, the same name is a new moment.
		c.moment(ChatParser.moment("New item added to your collection log: Draconic visage", 60 * MIN, null));
		assertEquals(4, c.current().moments.size());
	}

	@Test
	public void experienceGainedAwayIsNotThisSessions()
	{
		Chronicle c = new Chronicle();
		c.begin(0, "Zezima", GAP);
		c.xp("Fishing", 1_000_000, 80, 0);
		c.xp("Fishing", 1_100_000, 81, 1000);
		c.pause(MIN);
		c.begin(5 * MIN, "Zezima", GAP);
		// Fished on mobile during the break: 50k more and a level.
		c.resume("Fishing", 1_150_000, 82);
		c.resume("Mining", 0, 1);
		Session.SkillLine line = c.current().skills.get("Fishing");
		assertEquals(100_000, line.gained());
		assertEquals(1, line.getLevel() - line.getStartLevel());
		c.xp("Fishing", 1_160_000, 82, 6 * MIN);
		assertEquals(110_000, c.current().totalXp());
		// A reading the client was not ready for changes nothing.
		c.resume("Fishing", 0, 1);
		assertEquals(110_000, c.current().totalXp());
	}

	@Test
